import { CloseButton as HeroCloseButton, cn } from "@heroui/react"

/**
 * Tone that drives the close button's colour + hover tint. Maps 1:1 to the app's
 * semantic colours; `neutral` is the quiet grey default.
 */
export type ElementCloseButtonTone = "neutral" | "accent" | "success" | "warning" | "danger"

/**
 * Per-tone colour + hover fill (LITERAL classes ΓÇö Tailwind can't see interpolated
 * ones). The `!` beats HeroUI's UNLAYERED `.close-button--default` base
 * (`bg-default text-muted`), which a plain utility would lose to. This is the SAME
 * "text-<tone> + hover:bg-<tone>/10" treatment `Callout` used ad-hoc, now shared so
 * every close button reads consistently: hover = a tint of its OWN tone.
 */
const TONE: Record<ElementCloseButtonTone, string> = {
    neutral: "!text-muted hover:!bg-default",
    accent: "!text-accent-soft-foreground hover:!bg-accent-soft",
    success: "!text-success-soft-foreground hover:!bg-success-soft",
    warning: "!text-warning-soft-foreground hover:!bg-warning-soft",
    danger: "!text-danger-soft-foreground hover:!bg-danger-soft",
}

/** Props for {@link ElementCloseButton}. */
export interface ElementCloseButtonProps {
    /** Accessible label (the caller passes an already-resolved string, e.g. `t("common.close")`). */
    label: string
    /** Fired when the close/dismiss button is pressed. */
    onPress: () => void
    /**
     * Colour + hover-tint tone. Defaults to `neutral`. Pass the OWNER's tone so the
     * X reads tonal (a warning callout ΓåÆ warning X, an accent chip ΓåÆ accent X).
     */
    tone?: ElementCloseButtonTone
}

/**
 * The design-system close/dismiss "├ù" ΓÇö a thin wrapper over HeroUI `CloseButton`
 * that bakes the shared look so callers don't re-style it ad-hoc:
 *
 * - **TRANSPARENT at rest** (icon only, no grey pill) ΓÇö a fill of its own tone only
 *   on hover, so it never sits as a permanent grey square.
 * - **Tonal colour** (`tone`) ΓÇö the ├ù and its hover tint follow the owner's semantic
 *   colour, matching the surface it dismisses.
 *
 * All styling is per-instance (`!` utilities on THIS element), so it never leaks to
 * close buttons elsewhere (no global `.close-button` override). Use for a Callout
 * dismiss, a removable chip's cancel-X, a dismissible banner, etc.
 *
 * No house atom wraps HeroUI's `CloseButton` yet, so the vendor import stays here
 * (single unwrapped primitive, no atom equivalent to reuse) rather than being
 * invented as a new shared atom.
 *
 * @param props - {@link ElementCloseButtonProps}
 * @see Story: .storybook/stories/blocks/buttons/ElementCloseButton/ElementCloseButton.stories
 */
export const ElementCloseButton = ({ label, onPress, tone = "neutral" }: ElementCloseButtonProps) => {
    return (
        <HeroCloseButton
            data-tier="atom"
            data-component="ElementCloseButton"
            aria-label={label}
            onPress={onPress}
            className={cn("shrink-0", "!bg-transparent", TONE[tone])}
        />
    )
}

"use client"

import React from "react"
import { Button, cn } from "@heroui/react"
import type { ReactNode } from "react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for the {@link FloatingActionButton} block. */
export interface FloatingActionButtonProps extends WithClassNames<undefined> {
    /** Press handler (open the target overlay / action). */
    onPress: () => void
    /** Accessible name for the icon-only button. */
    ariaLabel: string
    /**
     * Icon content, centered and sized by the icon-only button (HeroUI sizes the
     * child svg to `size-5`, or `size-4` on ΓëÑsm) ΓÇö pass a bare icon, no size class.
     */
    children?: ReactNode
}

/**
 * A bottom-right floating action button ΓÇö a round, shadowed accent circle wrapping
 * a HeroUI `<Button isIconOnly>` (so the `children` icon inherits the button's
 * native svg sizing). Pure + props-only; owns its look + fixed placement.
 *
 * @param props - {@link FloatingActionButtonProps}
 * @see Story: .storybook/stories/blocks/buttons/FloatingActionButton/FloatingActionButton.stories
 */
export const FloatingActionButton = ({
    onPress,
    ariaLabel,
    children,
    className,
}: FloatingActionButtonProps) => {
    return (
        <Button
            isIconOnly
            variant="primary"
            aria-label={ariaLabel}
            onPress={onPress}
            className={cn(
                "fixed bottom-6 right-[calc(var(--app-rail-w,0px)+1.5rem)] z-40 rounded-full shadow-lg",
                className,
            )}
        >
            {children}
        </Button>
    )
}

"use client"

import React from "react"
import type { ReactNode } from "react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { GroupPressableCard } from "@/components/blocks/cards/GroupPressableCard"

/** One selectable recall grade in a {@link RatingBar}. */
export interface RatingOption {
    /** SM-2 grade value reported to {@link RatingBarProps.onRate} (0=Again ΓÇª 3=Easy). */
    grade: number
    /** Localized button label (resolved by the caller ΓÇö blocks carry no i18n). */
    label: ReactNode
    /** Optional secondary line under the label (e.g. the next-interval preview). */
    hint?: ReactNode
}

/** Props for the {@link RatingBar} block. */
export interface RatingBarProps {
    /** Ordered grades to offer, weakest recall first (Again ΓåÆ Easy). */
    options: Array<RatingOption>
    /** Called with the chosen grade. */
    onRate: (grade: number) => void
    /**
     * Accessible name for the grade group, localized by the caller (blocks carry
     * no i18n) ΓÇö e.g. "Choose recall level". Without it a screen reader hears four
     * loose buttons with nothing tying them together.
     */
    ariaLabel: string
    /** Disables every button while a review is in flight. */
    isPending?: boolean
}

/**
 * Grade ΓåÆ RAW palette colour for the shared verdict band's `color` escape hatch
 * (`VerdictBand.color` ΓåÆ `border-l-${color}`, `card.md` ┬º3i). A grade is a TIER (like a
 * difficulty level), not a status/alert, so it uses the difficulty HUE ramp
 * (roseΓåÆemerald), NOT the 4 semantic `variant` tokens (only 4 tiers; a semantic token
 * would double up or wrongly imply "this failed" for the weakest grade). Runs
 * weakestΓåÆstrongest RECALL: grade 0 (Again, hardest to recall) = rose, grade 3 (Easy) = emerald.
 */
const GRADE_COLOR: Record<number, string> = {
    0: "rose-500",
    1: "orange-500",
    2: "amber-500",
    3: "emerald-500",
}

/**
 * The SM-2 recall-rating bar: a row of FOUR equal-width grade TILES (Again / Hard
 * / Good / Easy) the learner taps ΓÇö or presses `1`ΓÇô`4` ΓÇö after revealing a
 * flashcard's answer. Each tile carries a tier-colored LEFT BAND (the shared
 * `withVerdict` band ΓÇö `card.md` ┬º3i, colours from {@link GRADE_COLOR}), a
 * keyboard-key hint (a neutral `Chip` ΓÇö canon `elements/chip.md` ┬º1, no hand-rolled
 * `<kbd>` pill), and an optional next-interval preview.
 *
 * The tiles + their grid + the 1ΓÇô4 shortcut are a `GroupPressableCard`, so
 * this block only owns the tile ANATOMY. Grading is an ACTION ΓÇö nothing stays
 * selected, no ring, no outline ΓÇö which is why this is not a
 * `SelectableCardGroup` (that block's accent outline is reserved for a REAL
 * persisted choice; nothing here persists). Restrained "pro reviewer" look
 * (Anki/RemNote), NOT a rainbow of emoji buttons. Labels/hints arrive
 * localized from the caller.
 *
 * @param props - {@link RatingBarProps}
 */
export const RatingBar = ({ options, onRate, ariaLabel, isPending = false}: RatingBarProps) => (
    <GroupPressableCard
        ariaLabel={ariaLabel}
        // measured: below a 384px container the hint line wraps and the tiles grow
        // to 104px tall; at 384px (4 ├ù 90px) it settles. So four-across only from
        // `@sm`, two-up below ΓÇö never the 4 ├ù 58px sliver a viewport breakpoint
        // produced when this sat in a narrow slot on a wide screen.
        columns={{ base: 2, sm: 4 }}
        gap={3}
        keyboardShortcut
        items={options.map((option, position) => ({
            key: String(option.grade),
            onPress: () => onRate(option.grade),
            isDisabled: isPending,
            // the grade's tier drives the shared verdict LEFT-BAND (card.md ┬º3i) ΓÇö the
            // grade's ONLY colour signal. `pl-4` clears the band from the label.
            withVerdict: { enable: true, color: GRADE_COLOR[option.grade] },
            className: "flex flex-col gap-2 py-2 pr-3 pl-4",
            content: () => (
                <>
                    <span className="flex items-center justify-between gap-2">
                        <span className="text-sm font-medium text-foreground">{option.label}</span>
                        <Chip tone="default" text={String(position + 1)} />
                    </span>
                    {option.hint !== undefined ? (
                        <Typography size="xs" color="muted" text={option.hint} />
                    ) : null}
                </>
            ),
        }))}
    />
)

import React from "react"
/** Props for the {@link CoverImage} block. */
export interface CoverImageProps {
    /** Image source URL (null/undefined ΓåÆ empty framed surface). */
    src?: string | null
    /** Accessible alt text. */
    alt: string
}

/**
 * A framed cover/thumbnail image: fixed 16:9 box, rounded surface, lazy-loaded,
 * `object-cover` so any aspect fills cleanly. Owns the whole look (radius /
 * surface / crop) so features pass only `src` + `alt`. Reusable for course /
 * blog / changelog covers.
 *
 * @param props - {@link CoverImageProps}
 * @see Story: .storybook/stories/blocks/media/CoverImage/CoverImage.stories
 */
export const CoverImage = ({
    src,
    alt}: CoverImageProps) => {
    return (
        <div className={"aspect-video w-full overflow-hidden rounded-2xl bg-surface-secondary"}>
            {src ? (
                <img
                    src={src}
                    alt={alt}
                    loading="lazy"
                    className="size-full object-cover"
                />
            ) : null}
        </div>
    )
}

import React from "react"
/** Props for {@link QRCode}. */
export interface QRCodeProps {
    size: number
    data: string
    icon?: React.ReactNode
}

/** Renders a QR code image for `data`, with an optional overlay icon in the center. */
export const QRCode = ({ size, data, icon}: QRCodeProps) => {
    const src = `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encodeURIComponent(data)}`
    return (
        <div className={"relative inline-flex shrink-0"} style={{ width: size, height: size }}>
            <img alt="" width={size} height={size} src={src} className="rounded-lg" />
            {icon ? (
                <div className="absolute left-1/2 top-1/2 flex -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-background p-1 shadow-sm">
                    {icon}
                </div>
            ) : null}
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useRef, useState } from "react"
import { VideoControls, type QualityLevel } from "../VideoControls"
import type { MediaPlayerClass } from "dashjs"

/** Props for {@link MpegDash}. */
export interface MpegDashPlayerProps {
    /** URL pointing to an MPEG-DASH .mpd manifest. */
    src: string
}

/** One bitrate rendition reported by the legacy dashjs `getBitrateInfoListFor`. */
interface DashBitrateInfo {
    /** Index of this quality rendition (used to pin playback). */
    qualityIndex: number
    /** Pixel height of the rendition (e.g. 720). */
    height: number
    /** Encoded bitrate of the rendition, in bits per second. */
    bitrate: number
}

/** Payload of the dashjs `playbackTimeUpdated` event. */
interface DashPlaybackTimeUpdatedEvent {
    /** Current playback position, in seconds. */
    time: number
    /** Seconds remaining until the end of the stream (0 at the end). */
    timeToEnd: number
}

/**
 * Legacy dashjs quality APIs that exist at runtime but were dropped from the
 * v5 `MediaPlayerClass` typings ΓÇö narrowed here so we can call them without `any`.
 */
interface DashLegacyQualityApi {
    /** Returns the available bitrate renditions for a media type (`"video"`). */
    getBitrateInfoListFor: (type: string) => Array<DashBitrateInfo>
    /** Pins playback to a specific quality index for a media type. */
    setQualityFor: (type: string, qualityIndex: number) => void
}

/**
 * MPEG-DASH adaptive video player using `dashjs`.
 * Custom HeroUI controls with quality / bitrate selector.
 *
 * Pattern based on cistudy-client-2 DashVideoPlayer.
 */
export const MpegDash = ({ src }: MpegDashPlayerProps) => {
    const videoRef = useRef<HTMLVideoElement | null>(null)
    const containerRef = useRef<HTMLDivElement | null>(null)
    const playerRef = useRef<MediaPlayerClass | null>(null)

    const [isPlaying, setIsPlaying] = useState(false)
    const [currentTime, setCurrentTime] = useState(0)
    const [duration, setDuration] = useState(0)
    const [volume, setVolume] = useState(0.5)
    const [isMuted, setIsMuted] = useState(false)
    const [hideControls, setHideControls] = useState(true)

    // DASH-specific
    const [qualityLevels, setQualityLevels] = useState<Array<QualityLevel>>([])
    const [selectedQuality, setSelectedQuality] = useState(-1) // -1 = auto

    // ΓöÇΓöÇ Initialize dashjs ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    useEffect(() => {
        let mounted = true

        const init = async () => {
            const video = videoRef.current
            if (!video) return

            const dashjsModule = await import("dashjs")
            if (!mounted) return

            const player = dashjsModule.MediaPlayer().create()
            playerRef.current = player
            player.initialize(video, src, false)

            player.on("streamInitialized", () => {
                const bitrates = (player as unknown as DashLegacyQualityApi).getBitrateInfoListFor("video")
                setQualityLevels(
                    bitrates.map((rendition) => ({
                        index: rendition.qualityIndex,
                        height: rendition.height,
                        bitrate: rendition.bitrate,
                    })),
                )
                setDuration(player.duration())
            })

            player.on("playbackTimeUpdated", (event: DashPlaybackTimeUpdatedEvent) => {
                setCurrentTime(event.time)
                if (event.timeToEnd === 0) {
                    player.pause()
                    setIsPlaying(false)
                }
            })
        }

        init()

        return () => {
            mounted = false
            playerRef.current?.destroy()
            playerRef.current = null
        }
    }, [src])

    // ΓöÇΓöÇ Quality change handler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    useEffect(() => {
        const player = playerRef.current
        if (!player) return
        if (selectedQuality === -1) {
            // Auto
            player.updateSettings({
                streaming: {
                    abr: {
                        autoSwitchBitrate: { audio: true, video: true },
                    },
                },
            })
        } else {
            player.updateSettings({
                streaming: {
                    abr: {
                        autoSwitchBitrate: { audio: false, video: false },
                    },
                },
            })
            ;(player as unknown as DashLegacyQualityApi).setQualityFor("video", selectedQuality)
        }
    }, [selectedQuality])

    // ΓöÇΓöÇ Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const onPlayPause = useCallback(() => {
        const player = playerRef.current
        if (!player) return
        if (isPlaying) {
            player.pause()
            setIsPlaying(false)
        } else {
            player.play()
            setIsPlaying(true)
        }
    }, [isPlaying])

    const onSeek = useCallback((time: number) => {
        const player = playerRef.current
        if (!player) return
        player.seek(time)
        setCurrentTime(time)
    }, [])

    const onVolumeChange = useCallback((vol: number) => {
        const player = playerRef.current
        if (!player) return
        player.setVolume(vol)
        setVolume(vol)
        if (vol > 0) setIsMuted(false)
    }, [])

    const onMuteToggle = useCallback(() => {
        const player = playerRef.current
        if (!player) return
        const next = !isMuted
        player.setMute(next)
        setIsMuted(next)
    }, [isMuted])

    const onQualityChange = useCallback((index: number) => {
        setSelectedQuality(index)
    }, [])

    const onFullscreen = useCallback(() => {
        const el = containerRef.current
        if (!el) return
        if (document.fullscreenElement) {
            document.exitFullscreen()
        } else {
            el.requestFullscreen()
        }
    }, [])

    return (
        // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- hover/focus only toggles the visibility of the control bar; every control is a real, independently keyboard-focusable button inside VideoControls
        <div
            ref={containerRef}
            className="relative aspect-video overflow-hidden rounded-large bg-black"
            onMouseEnter={() => setHideControls(false)}
            onMouseLeave={() => setHideControls(true)}
            onFocus={() => setHideControls(false)}
            onBlur={() => setHideControls(true)}
        >
            <video
                ref={videoRef}
                className="h-full w-full object-contain"
                playsInline
                onClick={onPlayPause}
                aria-label="MPEG-DASH playback"
            />
            <VideoControls
                isPlaying={isPlaying}
                currentTime={currentTime}
                duration={duration}
                volume={volume}
                isMuted={isMuted}
                onPlayPause={onPlayPause}
                onSeek={onSeek}
                onVolumeChange={onVolumeChange}
                onMuteToggle={onMuteToggle}
                onFullscreen={onFullscreen}
                qualityLevels={qualityLevels}
                selectedQuality={selectedQuality}
                onQualityChange={onQualityChange}
                hidden={hideControls}
            />
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useRef, useState } from "react"
import { VideoControls } from "../VideoControls"

/** Props for {@link Standard}. */
export interface StandardPlayerProps {
    /** Direct video URL (mp4, webm, ogg). */
    src: string
}

/**
 * Standard (MP4) video player with custom HeroUI controls.
 * Uses native `<video>` element for playback.
 */
export const Standard = ({ src }: StandardPlayerProps) => {
    const videoRef = useRef<HTMLVideoElement | null>(null)
    const containerRef = useRef<HTMLDivElement | null>(null)

    const [isPlaying, setIsPlaying] = useState(false)
    const [currentTime, setCurrentTime] = useState(0)
    const [duration, setDuration] = useState(0)
    const [volume, setVolume] = useState(0.5)
    const [isMuted, setIsMuted] = useState(false)
    const [hideControls, setHideControls] = useState(true)

    // ΓöÇΓöÇ Video element event bindings ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    useEffect(() => {
        const video = videoRef.current
        if (!video) return

        const onLoadedMetadata = () => setDuration(video.duration)
        const onTimeUpdate = () => setCurrentTime(video.currentTime)
        const onEnded = () => setIsPlaying(false)

        video.addEventListener("loadedmetadata", onLoadedMetadata)
        video.addEventListener("timeupdate", onTimeUpdate)
        video.addEventListener("ended", onEnded)

        return () => {
            video.removeEventListener("loadedmetadata", onLoadedMetadata)
            video.removeEventListener("timeupdate", onTimeUpdate)
            video.removeEventListener("ended", onEnded)
        }
    }, [])

    // ΓöÇΓöÇ Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const onPlayPause = useCallback(() => {
        const video = videoRef.current
        if (!video) return
        if (video.paused) {
            video.play()
            setIsPlaying(true)
        } else {
            video.pause()
            setIsPlaying(false)
        }
    }, [])

    const onSeek = useCallback((time: number) => {
        const video = videoRef.current
        if (!video) return
        video.currentTime = time
        setCurrentTime(time)
    }, [])

    const onVolumeChange = useCallback((vol: number) => {
        const video = videoRef.current
        if (!video) return
        video.volume = vol
        setVolume(vol)
        if (vol > 0) setIsMuted(false)
    }, [])

    const onMuteToggle = useCallback(() => {
        const video = videoRef.current
        if (!video) return
        video.muted = !video.muted
        setIsMuted(video.muted)
    }, [])

    const onFullscreen = useCallback(() => {
        const el = containerRef.current
        if (!el) return
        if (document.fullscreenElement) {
            document.exitFullscreen()
        } else {
            el.requestFullscreen()
        }
    }, [])

    return (
        // eslint-disable-next-line jsx-a11y/no-static-element-interactions -- hover/focus only toggles the visibility of the control bar; every control is a real, independently keyboard-focusable button inside VideoControls
        <div
            ref={containerRef}
            className="relative aspect-video overflow-hidden rounded-large bg-black"
            onMouseEnter={() => setHideControls(false)}
            onMouseLeave={() => setHideControls(true)}
            onFocus={() => setHideControls(false)}
            onBlur={() => setHideControls(true)}
        >
            <video
                ref={videoRef}
                className="h-full w-full object-contain"
                src={src}
                playsInline
                onClick={onPlayPause}
                aria-label="Standard video playback"
            />
            <VideoControls
                isPlaying={isPlaying}
                currentTime={currentTime}
                duration={duration}
                volume={volume}
                isMuted={isMuted}
                onPlayPause={onPlayPause}
                onSeek={onSeek}
                onVolumeChange={onVolumeChange}
                onMuteToggle={onMuteToggle}
                onFullscreen={onFullscreen}
                hidden={hideControls}
            />
        </div>
    )
}

"use client"

import { ArrowsOutIcon } from "@phosphor-icons/react"
import React from "react"
import { Button } from "@heroui/react"
/** Props for {@link FullscreenButton}. */
