"use client"

import { GearIcon as GearSixIcon } from "@phosphor-icons/react"
import React from "react"
import { Dropdown, DropdownItem, DropdownMenu, DropdownTrigger } from "@heroui/react"
import { useCallback, useMemo } from "react"
import { AUTO_QUALITY_INDEX } from "../constants"
import type { QualityLevel } from "../types"

/** Props for {@link QualitySelector}. */
export interface QualitySelectorProps {
    /** Available quality renditions (excluding the synthetic Auto entry). */
    qualityLevels: Array<QualityLevel>
    /** Currently selected quality index (`-1` = auto). */
    selectedQuality: number
    /** Fired with the chosen quality index. */
    onQualityChange: (index: number) => void
}

/**
 * Dropdown that lets the viewer pin an adaptive bitrate / quality level.
 *
 * Presentational: prepends a synthetic "Auto" option and forwards the
 * selected key, no playback logic.
 * @param props - Levels, current selection, and the change callback.
 */
export const QualitySelector = ({
    qualityLevels,
    selectedQuality,
    onQualityChange}: QualitySelectorProps) => {
    /** Human-readable label for a quality level. */
    const qualityLabel = useCallback(
        (quality: QualityLevel) =>
            quality.index === AUTO_QUALITY_INDEX
                ? "Auto"
                : `${quality.height}p (${Math.round(quality.bitrate / 1000)}k)`,
        [],
    )

    /** All quality options including the synthetic Auto entry. */
    const allQualities = useMemo<Array<QualityLevel>>(
        () => [
            {
                index: AUTO_QUALITY_INDEX,
                height: 0,
                bitrate: 0,
            },
            ...qualityLevels,
        ],
        [
            qualityLevels,
        ],
    )

    /** Currently selected dropdown key set. */
    const selectedKeys = useMemo(
        () => new Set([
            String(selectedQuality ?? AUTO_QUALITY_INDEX),
        ]),
        [
            selectedQuality,
        ],
    )

    /** Resolve the chosen key back into a numeric quality index. */
    const onSelectionChange = useCallback(
        (keys: "all" | Set<React.Key>) => {
            if (keys === "all") return
            const key = Array.from(keys)[0]
            if (key !== undefined) {
                onQualityChange(Number(key))
            }
        },
        [
            onQualityChange,
        ],
    )

    return (
        <Dropdown className={""}>
            <DropdownTrigger aria-label="Quality">
                <div className="flex h-8 min-w-8 cursor-pointer items-center justify-center rounded-medium border-none text-white hover:bg-white/20">
                    <GearSixIcon className="h-5 w-5" />
                </div>
            </DropdownTrigger>
            <DropdownMenu
                aria-label="Quality levels"
                selectionMode="single"
                selectedKeys={selectedKeys}
                onSelectionChange={onSelectionChange}
            >
                {allQualities.map((quality) => (
                    <DropdownItem key={String(quality.index)}>
                        {qualityLabel(quality)}
                    </DropdownItem>
                ))}
            </DropdownMenu>
        </Dropdown>
    )
}

"use client"

import React from "react"
import { Slider } from "@heroui/react"
import { useCallback } from "react"

/** Props for {@link SeekBar}. */
export interface SeekBarProps {
    /** Current playback position in seconds. */
    currentTime: number
    /** Total media duration in seconds. */
    duration: number
    /** Fired with the requested seek position in seconds. */
    onSeek: (time: number) => void
}

/**
 * Horizontal scrubber for seeking within the media timeline.
 *
 * Presentational: forwards slider changes to {@link SeekBarProps.onSeek}.
 * @param props - Current time, duration, and the seek callback.
 */
export const SeekBar = ({
    currentTime,
    duration,
    onSeek}: SeekBarProps) => {
    /** Normalize the slider value to a number before bubbling the seek. */
    const onChange = useCallback(
        (value: number | Array<number>) => onSeek(value as number),
        [
            onSeek,
        ],
    )

    return (
        <Slider
            aria-label="Seek"
            step={0.1}
            minValue={0}
            maxValue={duration || 1}
            value={currentTime}
            onChange={onChange}
            className={"mb-2"}
        />
    )
}

"use client"

import React, { useMemo } from "react"
import { formatTime } from "../utils"

/** Props for {@link TimeDisplay}. */
export interface TimeDisplayProps {
    /** Current playback position in seconds. */
    currentTime: number
    /** Total media duration in seconds. */
    duration: number
}

/**
 * Monospace `current / total` time readout.
 *
 * Presentational: derives formatted strings only.
 * @param props - Current time and duration in seconds.
 */
export const TimeDisplay = ({
    currentTime,
    duration}: TimeDisplayProps) => {
    /** Formatted current playback position. */
    const current = useMemo(
        () => formatTime(currentTime),
        [
            currentTime,
        ],
    )

    /** Formatted total duration. */
    const total = useMemo(
        () => formatTime(duration),
        [
            duration,
        ],
    )

    return (
        <span className={"select-none text-xs font-mono text-white/80"}>
            {current}{" "}
            <span className="text-white/40">/</span>{" "}
            {total}
        </span>
    )
}

"use client"

import { SpeakerHighIcon, SpeakerSlashIcon } from "@phosphor-icons/react"
import React from "react"
import { Button, Popover, Slider } from "@heroui/react"
import { useCallback, useMemo } from "react"


/** Props for {@link VolumeControl}. */
export interface VolumeControlProps {
    /** Current volume in the `0..1` range. */
    volume: number
    /** Whether audio is currently muted. */
    isMuted: boolean
    /** Fired with the requested volume in the `0..1` range. */
    onVolumeChange: (vol: number) => void
    /** Fired when the user toggles mute. */
    onMuteToggle: () => void
}

/**
 * Mute toggle button with a popover volume slider.
 *
 * Presentational: derives icon + effective slider value, no logic.
 * @param props - Volume, mute state, and the change/toggle callbacks.
 */
export const VolumeControl = ({
    volume,
    isMuted,
    onVolumeChange,
    onMuteToggle}: VolumeControlProps) => {
    /** Slider should sit at zero whenever audio is muted. */
    const sliderValue = useMemo(
        () => (isMuted ? 0 : volume),
        [
            isMuted,
            volume,
        ],
    )

    /** Whether to render the muted icon (explicitly muted or silent). */
    const isSilent = useMemo(
        () => isMuted || volume === 0,
        [
            isMuted,
            volume,
        ],
    )

    /** Normalize the slider value to a number before bubbling the change. */
    const onChange = useCallback(
        (value: number | Array<number>) => onVolumeChange(value as number),
        [
            onVolumeChange,
        ],
    )

    return (
        <Popover>
            <Popover.Trigger>
                <Button
                    isIconOnly
                    variant="ghost"
                    aria-label="Volume"
                    onPress={onMuteToggle}
                    className={"text-white hover:bg-white/20 border-none min-w-8 h-8"}
                >
                    {isSilent ? (
                        <SpeakerSlashIcon className="h-5 w-5" />
                    ) : (
                        <SpeakerHighIcon className="h-5 w-5" />
                    )}
                </Button>
            </Popover.Trigger>
            <Popover.Content className="w-8 bg-black/90 p-2">
                <Slider
                    aria-label="Volume"
                    orientation="vertical"
                    step={0.01}
                    minValue={0}
                    maxValue={1}
                    value={sliderValue}
                    onChange={onChange}
                    className="h-20"
                />
            </Popover.Content>
        </Popover>
    )
}

