/** Props for {@link VideoControls}. */
export interface VideoControlsProps {
    /** Whether playback is currently active. */
    isPlaying: boolean
    /** Current playback position in seconds. */
    currentTime: number
    /** Total media duration in seconds. */
    duration: number
    /** Current volume in the `0..1` range. */
    volume: number
    /** Whether audio is currently muted. */
    isMuted: boolean
    /** Fired when the user toggles play/pause. */
    onPlayPause: () => void
    /** Fired with the requested seek position in seconds. */
    onSeek: (time: number) => void
    /** Fired with the requested volume in the `0..1` range. */
    onVolumeChange: (vol: number) => void
    /** Fired when the user toggles mute. */
    onMuteToggle: () => void
    /** Fired when the user requests fullscreen toggle. */
    onFullscreen?: () => void
    /** DASH-only: available quality levels. */
    qualityLevels?: Array<QualityLevel>
    /** DASH-only: currently selected quality index (`-1` = auto). */
    selectedQuality?: number
    /** DASH-only: callback to change quality. */
    onQualityChange?: (index: number) => void
    /** Whether to hide the control bar. */
    hidden?: boolean
}

/**
 * Shared video control bar overlay.
 *
 * Used by the Standard and MpegDash players. Composes play/pause, seek slider,
 * volume, time display, optional quality selector (DASH), and fullscreen into a
 * single bottom-anchored overlay. Presentational: derives visibility classes and
 * quality availability, no playback logic.
 * @param props - Playback state plus the control callbacks.
 */
export const VideoControls = ({
    isPlaying,
    currentTime,
    duration,
    volume,
    isMuted,
    onPlayPause,
    onSeek,
    onVolumeChange,
    onMuteToggle,
    onFullscreen,
    qualityLevels,
    selectedQuality,
    onQualityChange,
    hidden = false}: VideoControlsProps) => {
    /** Whether to render the DASH quality selector. */
    const hasQuality = useMemo(
        () => Boolean(
            qualityLevels && qualityLevels.length > 0 && onQualityChange,
        ),
        [
            qualityLevels,
            onQualityChange,
        ],
    )

    /** Visibility classes toggled by the `hidden` flag. */
    const visibilityClassName = useMemo(
        () => (hidden ? "pointer-events-none opacity-0" : "opacity-100"),
        [
            hidden,
        ],
    )

    return (
        <div
            className={cn("absolute inset-x-0 bottom-0 z-20 bg-gradient-to-t from-black/80 via-black/40 to-transparent px-3 pb-3 pt-8 transition-opacity duration-300",
                visibilityClassName)}
        >
            <SeekBar
                currentTime={currentTime}
                duration={duration}
                onSeek={onSeek}
            />

            <div className="flex items-center justify-between gap-2">
                <div className="flex items-center gap-2">
                    <PlayPauseButton
                        isPlaying={isPlaying}
                        onPlayPause={onPlayPause}
                    />

                    <VolumeControl
                        volume={volume}
                        isMuted={isMuted}
                        onVolumeChange={onVolumeChange}
                        onMuteToggle={onMuteToggle}
                    />

                    <TimeDisplay
                        currentTime={currentTime}
                        duration={duration}
                    />
                </div>

                <div className="flex items-center gap-2">
                    {hasQuality && onQualityChange ? (
                        <QualitySelector
                            qualityLevels={qualityLevels ?? []}
                            selectedQuality={selectedQuality ?? -1}
                            onQualityChange={onQualityChange}
                        />
                    ) : null}

                    {onFullscreen ? (
                        <FullscreenButton onFullscreen={onFullscreen} />
                    ) : null}
                </div>
            </div>
        </div>
    )
}

"use client"

import React, { useMemo } from "react"

/** Props for {@link Youtube}. */
export interface YoutubePlayerProps {
    /** YouTube video URL (watch, short, embed, youtu.be). */
    url: string
    title?: string
}

// ---------------------------------------------------------------------------
// URL parser ΓÇö extract embed URL from any YouTube link format
// ---------------------------------------------------------------------------

const toYoutubeEmbedUrl = (raw: string): string | null => {
    const trimmed = raw.trim()
    if (!trimmed) return null

    try {
        const u = new URL(trimmed)
        const host = u.hostname.replace(/^www\./, "")

        if (
            host === "youtube.com" ||
            host === "m.youtube.com" ||
            host === "music.youtube.com"
        ) {
            const v = u.searchParams.get("v")
            if (v) return `https://www.youtube.com/embed/${v}`

            const parts = u.pathname.split("/").filter(Boolean)
            if (parts[0] === "embed" && parts[1])
                return `https://www.youtube.com/embed/${parts[1]}`
            if (parts[0] === "shorts" && parts[1])
                return `https://www.youtube.com/embed/${parts[1]}`
            if (parts[0] === "live" && parts[1])
                return `https://www.youtube.com/embed/${parts[1]}`
        }

        if (host === "youtu.be") {
            const id = u.pathname.split("/").filter(Boolean)[0]
            if (id) return `https://www.youtube.com/embed/${id}`
        }
    } catch {
        return null
    }
    return null
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

/**
 * YouTube embed player ΓÇö renders an iframe with no custom controls.
 */
export const Youtube = ({
    url,
    title = "YouTube video",
}: YoutubePlayerProps) => {
    const embedSrc = useMemo(() => toYoutubeEmbedUrl(url), [url])

    if (!embedSrc) {
        return (
            <div className="text-muted flex min-h-[12rem] items-center justify-center rounded-medium border border-dashed p-4 text-center text-sm">
                Invalid or unsupported YouTube URL.
            </div>
        )
    }

    return (
        <iframe
            title={title}
            className="aspect-video w-full rounded-large"
            src={embedSrc}
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
            allowFullScreen
        />
    )
}

"use client"
import React, { useMemo } from "react"
import { Standard } from "./Standard"
import { MpegDash } from "./MpegDash"
import { Youtube } from "./Youtube"
import { LessonVideoType } from "@/modules/types/enums/lesson-video-type"
import { VideoHostPlatform } from "@/modules/types/enums/video-host-platform"
import { VideoRendererType } from "@/modules/types/enums/video-renderer-type"

// ---------------------------------------------------------------------------
// Resolve which sub-player to use
// ---------------------------------------------------------------------------

/** True when the URL is a YouTube watch/share link. */
const isYoutubeUrl = (url?: string): boolean => /youtube\.com|youtu\.be/i.test(url ?? "")

/** True when the URL points at an MPEG-DASH `.mpd` manifest (ignoring query/hash). */
const isMpegDashUrl = (url?: string): boolean => /\.mpd(\?|#|$)/i.test(url ?? "")

const resolveRendererType = (
    url: string | undefined,
    videoType?: LessonVideoType,
    hostPlatform?: VideoHostPlatform,
): VideoRendererType => {
    // an explicit YouTube platform, or a YouTube URL, always wins
    if (hostPlatform === VideoHostPlatform.Youtube || isYoutubeUrl(url)) {
        return VideoRendererType.Youtube
    }
    // an explicit delivery format takes precedence over URL sniffing
    if (videoType === LessonVideoType.MpegDash) return VideoRendererType.MpegDash
    if (videoType === LessonVideoType.Standard) return VideoRendererType.Standard
    // no explicit type ΓåÆ infer from the URL: `.mpd` is DASH, everything else
    // (mp4/webm/ΓÇª) plays through the native Standard player
    if (isMpegDashUrl(url)) return VideoRendererType.MpegDash
    return VideoRendererType.Standard
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/** Props for {@link VideoRenderer}. */
export interface VideoRendererProps {
    url: string
    hostPlatform?: VideoHostPlatform
    /** Video delivery format ΓÇö Standard (mp4) or MpegDash. Defaults to Standard. */
    videoType?: LessonVideoType
    /** Explicit renderer type override. Takes precedence over auto-resolve. */
    rendererType?: VideoRendererType
    title?: string
}

/**
 * Universal video renderer ΓÇö picks 1 of 3 sub-players based on type:
 *
 * | Type       | Player          | Controls          |
 * |------------|-----------------|-------------------|
 * | Standard   | `<video>`       | Custom HeroUI     |
 * | MpegDash   | dashjs          | Custom + Quality  |
 * | Youtube    | iframe          | YouTube built-in  |
 */
export const VideoRenderer = ({
    url,
    hostPlatform,
    videoType,
    rendererType,
    title,
}: VideoRendererProps) => {
    const type =
        rendererType ?? resolveRendererType(url, videoType, hostPlatform)

    const renderContent = () => {
        if (!url?.trim()) {
            return (
                <div className="text-muted flex min-h-[12rem] items-center justify-center rounded-medium border border-dashed p-4 text-center text-sm">
                    No video URL.
                </div>
            )
        }

        switch (type) {
        case VideoRendererType.MpegDash:
            return <MpegDash src={url} />
        case VideoRendererType.Youtube:
            return <Youtube url={url} title={title} />
        case VideoRendererType.Standard:
        default:
            return <Standard src={url} />
        }
    }

    const content = useMemo(
        () => renderContent(),
        [url, type, title],
    )

    return (
        <div className="w-full aspect-video rounded-large overflow-hidden">
            {content}
        </div>
    )
}

import React from "react"
import { Typography, cn } from "@heroui/react"

/** One day's bar in a {@link DeadlineCallout}'s forecast row. */
export interface DeadlineCalloutForecastBar {
    /** Short label under the bar (e.g. a weekday abbreviation). */
    label: string
    /** Fill height as a share of the row, `0..1` ΓÇö the caller normalizes against the busiest day. */
    ratio: number
    /** True marks this as the overload day ("will pile up") ΓÇö fills danger instead of the neutral accent tone. */
    spike?: boolean
}

/** Props for the {@link DeadlineCallout} block. */
export interface DeadlineCalloutProps {
    /** How many items are about to be lost ΓÇö rendered large inside the tinted panel. */
    count: number
    /** The deadline sentence (e.g. "12 cards will slip before Thursday"). */
    title: string
    /** Optional supporting line under the title, inside the tinted panel (what happens if the learner waits). */
    hint?: string
    /** Optional per-day forecast bars below the panel ΓÇö surfaces the load ahead so an overload day doesn't blindside the learner. Omit when there is no lookahead data yet. */
    forecast?: DeadlineCalloutForecastBar[]
    /** Optional closing line under the forecast (e.g. which day is overloaded + what to do about it). */
    caption?: string
}

/**
 * An urgency callout for items about to slip out of memory: a warning-soft
 * tinted panel carrying a big count + a deadline sentence, followed by an
 * optional per-day forecast bar row (one bar may be a red "spike" overload
 * day) and an optional closing caption. Verdict (count + sentence) ΓåÆ evidence
 * (forecast) ΓÇö the caller supplies the actual CTA button below this block,
 * same split as every other stats zone in the insight redesign.
 *
 * Unlike the generic {@link Callout} (a flat note for any tone), this block is
 * single-purpose: it ALWAYS carries a countdown, never a plain status message.
 *
 * Pure/props-only ΓÇö no store, no fetch.
 *
 * @param props - {@link DeadlineCalloutProps}
 * @see Story: .storybook/stories/blocks/stats/DeadlineCallout/DeadlineCallout.stories
 */
export const DeadlineCallout = ({
    count,
    title,
    hint,
    forecast,
    caption}: DeadlineCalloutProps) => {
    return (
        <div className={"flex flex-col gap-3"}>
            <div className="flex items-center gap-3 rounded-2xl border border-warning-soft-foreground bg-warning-soft p-3">
                <Typography type="h3" weight="bold" className="shrink-0 text-warning-soft-foreground">
                    {count}
                </Typography>
                <div className="flex min-w-0 flex-col gap-0">
                    <Typography type="body-sm" weight="semibold">
                        {title}
                    </Typography>
                    {hint ? (
                        <Typography type="body-xs" color="muted">
                            {hint}
                        </Typography>
                    ) : null}
                </div>
            </div>

            {forecast && forecast.length > 0 ? (
                <div className="flex items-end gap-2">
                    {forecast.map((bar, position) => (
                        // position-keyed: bars are a fixed lookahead window (e.g. next 7 days),
                        // never reordered/filtered at runtime like a normal list.
                        <div key={position} className="flex flex-1 flex-col items-center gap-1">
                            <div className="flex h-14 w-full items-end">
                                <div
                                    // min 6% keeps a near-empty day visible as a sliver instead of
                                    // vanishing (mirrors MockInterviewStats' trend-bar convention).
                                    style={{ height: `${Math.max(6, Math.round(bar.ratio * 100))}%` }}
                                    className={cn("w-full rounded-t", bar.spike ? "bg-danger/70" : "bg-accent/50")}
                                />
                            </div>
                            <Typography type="body-xs" color="muted">
                                {bar.label}
                            </Typography>
                        </div>
                    ))}
                </div>
            ) : null}

            {caption ? (
                <Typography type="body-xs" color="muted">
                    {caption}
                </Typography>
            ) : null}
        </div>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import { Typography } from "@heroui/react"
import {
    Cell,
    Pie,
    PieChart,
    ResponsiveContainer,
    Tooltip,
} from "recharts"
import { getLanguageColor, getLanguageLabel } from "@/modules/utils/language"

/** One language slice: its key + count. */
export interface LanguageDonutItem {
    /** Language enum value (drives colour + label). */
    key: string
    /** Count for this language (slice size). */
    value: number
}

/** Props for {@link LanguageDonut}. */
export interface LanguageDonutProps {
    /** Language buckets to plot. */
    items: Array<LanguageDonutItem>
    /** Centre big-number unit label (e.g. "solved" / "problems"). */
    unitLabel: string
    /** Accessible description of the donut. */
    ariaLabel: string
    /** Donut diameter in px. Defaults to 128. */
    size?: number
    /** Ring thickness in px (outer ΓêÆ inner radius). Defaults to 8 (matches a bar). */
    thickness?: number
}

/**
 * GitHub-style language-mix donut ΓÇö a recharts ring split by language (brand
 * colours via {@link getLanguageColor}), a centred total, and a colour-dot legend
 * with per-language count + share. Pure/props-only block; owns its look. Language
 * names use the shared display map (`csharp`ΓåÆC#, `cpp`ΓåÆC++).
 *
 * @param props - {@link LanguageDonutProps}
 * @see Story: .storybook/stories/blocks/stats/LanguageDonut/LanguageDonut.stories
 */
export const LanguageDonut = ({
    items,
    unitLabel,
    ariaLabel,
    size = 128,
    thickness = 8}: LanguageDonutProps) => {
    // total across languages ΓÇö denominator for the legend percentages
    const total = useMemo(
        () => items.reduce((sum, item) => sum + item.value, 0),
        [items],
    )

    if (items.length === 0 || total === 0) {
        return null
    }

    // exact px radii ΓåÆ a ring of precisely `thickness` px
    const outerRadius = size / 2
    const innerRadius = Math.max(0, outerRadius - thickness)

    return (
        <div className={"flex flex-col items-center gap-6 @app-sm:flex-row"}>
            {/* the donut ΓÇö labelled as an image for screen readers */}
            <div
                role="img"
                aria-label={ariaLabel}
                style={{ width: size, height: size }}
                className="relative shrink-0"
            >
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Tooltip
                            formatter={(value, name) => [
                                `${value}`,
                                getLanguageLabel(String(name)),
                            ]}
                        />
                        <Pie
                            data={items}
                            dataKey="value"
                            nameKey="key"
                            innerRadius={innerRadius}
                            outerRadius={outerRadius}
                            paddingAngle={2}
                            stroke="none"
                        >
                            {items.map((item) => (
                                <Cell
                                    key={item.key}
                                    fill={getLanguageColor(item.key)}
                                    aria-hidden
                                    focusable="false"
                                />
                            ))}
                        </Pie>
                    </PieChart>
                </ResponsiveContainer>
                {/* centre total */}
                <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center gap-0">
                    <Typography type="h3" weight="semibold">{total}</Typography>
                    <Typography type="body-xs" color="muted">{unitLabel}</Typography>
                </div>
            </div>

            {/* colour-coded legend with per-language count + share */}
            <div className="flex w-full flex-col gap-3">
                {items.map((item) => (
                    <div key={item.key} className="flex items-center gap-2">
                        <span
                            aria-hidden
                            className="size-3 shrink-0 rounded-full"
                            style={{ backgroundColor: getLanguageColor(item.key) }}
                        />
                        <Typography type="body-xs" color="muted" className="flex-1">
                            {getLanguageLabel(item.key)}
                        </Typography>
                        <Typography type="body-xs" color="muted">{item.value}</Typography>
                        <Typography type="body-xs" color="muted" className="w-10 shrink-0 text-right">
                            {Math.round((item.value / total) * 100)}%
                        </Typography>
                    </div>
                ))}
            </div>
        </div>
    )
}

import React from "react"
import { cn } from "@heroui/react"


/** One milestone node on the roadmap. */
export interface MilestoneRoadmapItem {
    /** Milestone title (used for the hover tooltip). */
    title: string
    /** Number of tasks passed in this milestone. */
    passedTasks: number
    /** Total tasks in this milestone. */
    totalTasks: number
}

/** Props for the {@link MilestoneRoadmap} block. */
export interface MilestoneRoadmapProps {
    /** Ordered milestones rendered left ΓåÆ right as dots + connectors. */
    milestones: ReadonlyArray<MilestoneRoadmapItem>
}

/**
 * Horizontal milestone roadmap: one dot per milestone joined by connectors,
 * coloured by completion (done = filled success, partial = ringed success,
 * not-started = muted). Scrolls horizontally so a long roadmap never crams.
 * Pure + props-only; the block owns all the dot/connector styling so feature
 * code stays style-free.
 * @see Story: .storybook/stories/blocks/stats/MilestoneRoadmap/MilestoneRoadmap.stories
 */
export const MilestoneRoadmap = ({ milestones}: MilestoneRoadmapProps) => {
    return (
        <div className={"flex items-center gap-0 overflow-x-auto pb-1"}>
            {milestones.map((milestone, index) => {
                const isDone = milestone.totalTasks > 0
                    && milestone.passedTasks === milestone.totalTasks
                const isPartial = milestone.passedTasks > 0
                    && milestone.passedTasks < milestone.totalTasks
                return (
                    <React.Fragment key={`${milestone.title}-${index}`}>
                        {index > 0 ? (
                            <span aria-hidden className="h-0.5 min-w-3 flex-1 bg-default/60" />
                        ) : null}
                        <span
                            title={`${milestone.title} ${milestone.passedTasks}/${milestone.totalTasks}`}
                            aria-hidden
                            className={cn(
                                "size-3 shrink-0 rounded-full",
                                isDone && "bg-success",
                                isPartial && "border-2 border-success",
                                !isDone && !isPartial && "bg-default",
                            )}
                        />
                    </React.Fragment>
                )
            })}
        </div>
    )
}

import React, { useMemo } from "react"
import { cn } from "@heroui/react"

/**
 * Color of the score based on the ratio compared to the threshold.
 */
type ScoreTone = "danger" | "warning" | "success"

const toneTextClass: Record<ScoreTone, string> = {
    danger: "text-danger-soft-foreground",
    warning: "text-warning-soft-foreground",
    success: "text-success-soft-foreground",
}

const resolveTone = (
    current: number,
    max: number,
    threshold: number,
): ScoreTone => {
    if (max <= 0 || !Number.isFinite(current) || !Number.isFinite(max)) {
        return "danger"
    }
    const ratio = Math.min(Math.max(current / max, 0), 1)
    const half = threshold / 2
    if (ratio < half) {
        return "danger"
    }
    if (ratio < threshold) {
        return "warning"
    }
    return "success"
}

/** Props for {@link _Score} ΓÇö presentational; the label + aria-label already resolved. */
export interface ScoreProps {
    /** Current score (numerator). */
    current: number
    /** Maximum score (denominator). */
    max: number
    /**
     * Pass ratio for `current / max`.
     * Below `threshold / 2`: danger; from half to below `threshold`: warning; at or above `threshold`: success.
     */
    threshold?: number
    /** Already-localized + already-formatted "current/max" fraction text. */
    label: string
    /** Already-localized + already-formatted aria-label. */
    ariaLabel: string
    /** Extra classes on the root element (typography, spacing). */
}

/**
 * Renders `current/max` with tone from the ratio against `threshold` (default 0.7).
 * @param props - {@link ScoreProps}
 */
export const _Score = ({
    current,
    max,
    threshold = 0.7,
    label,
    ariaLabel,
}: ScoreProps) => {
    const tone = useMemo(
        () => resolveTone(current, max, threshold),
        [current, max, threshold],
    )

    return (
        <div
            className={
                cn(
                    "font-medium tabular-nums text-4xl font-bold",
                    toneTextClass[tone]
                )
            }
            aria-label={ariaLabel}
        >
            {label}
        </div>
    )
}

import React from "react"
import { Typography } from "@heroui/react"
/** One topic cell in a {@link TopicMasteryGrid}. */
export interface TopicMasterySegment {
    /** Stable key. */
    key: string
    /** Display label (e.g. "Dynamic Programming"). */
    label: string
    /** Solved count ΓÇö drives both the printed number and the tint intensity. */
    solved: number
}

/** Props for the {@link TopicMasteryGrid} block. */
export interface TopicMasteryGridProps {
    /** Topics to show, already sorted (strongest first reads best). */
    topics: Array<TopicMasterySegment>
    /** Accessible summary of the whole grid (read instead of the cells). */
    ariaLabel: string
}

/**
 * Topic-mastery grid ΓÇö a LeetCode-style "what CS areas is this dev strong in"
 * heatmap. Each solved topic is a NEUTRAL chip whose tint deepens with the solved
 * count (relative to the strongest topic), with the count printed so the signal
 * never relies on colour alone. Neutral (not accent) so it doesn't compete with
 * the app's accent ΓÇö the printed count carries the magnitude. Honest (no hidden
 * topics, real counts) and compact. Pure/props-only; owns its look.
 *
 * @param props - {@link TopicMasteryGridProps}
 * @see Story: .storybook/stories/blocks/stats/TopicMasteryGrid/TopicMasteryGrid.stories
 */
export const TopicMasteryGrid = ({ topics, ariaLabel}: TopicMasteryGridProps) => {
    const max = topics.reduce((peak, topic) => Math.max(peak, topic.solved), 0) || 1
    return (
        <div
            role="img"
            aria-label={ariaLabel}
            className={"flex flex-wrap gap-2"}
        >
            {topics.map((topic) => {
                // deeper neutral tint the closer a topic is to the strongest (12%ΓÇô48%)
                const intensity = Math.round(12 + (topic.solved / max) * 36)
                return (
                    <span
                        key={topic.key}
                        style={{ backgroundColor: `color-mix(in srgb, var(--default) ${intensity}%, transparent)` }}
                        className="inline-flex items-center gap-2 rounded-full px-3 py-1"
                    >
                        <Typography type="body-xs" weight="medium">
                            {topic.label}
                        </Typography>
                        <Typography type="body-xs" color="muted">
                            {topic.solved}
                        </Typography>
                    </span>
                )
            })}
        </div>
    )
}

import React, { type ComponentType } from "react"
import type { ReactNode } from "react"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { Typography, type TypographyColor } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/** Semantic verdict tone ΓÇö drives the left accent border, the big value's color, and the meter fill. */
export type VerdictHeroBand = "danger" | "warning" | "success"

/** The meter row inside a {@link VerdictHeroCard} ΓÇö current progress toward an optional target mark. */
export interface VerdictHeroMeter {
    /** Current value, same unit as {@link VerdictHeroCardProps.value}. */
    value: number
    /** Denominator for the bar. @default 100 */
    max?: number
    /** Optional healthy-mark position on the bar (e.g. the "85% retention" line) ΓÇö omit when there is no known target yet. */
    target?: number
}

/** One mini stat in a {@link VerdictHeroCard}'s optional split row (e.g. "mature vs young" retention). */
export interface VerdictHeroSplit {
    /** Muted caption above the value (e.g. "Cards mastered") ΓÇö a buildable slot. */
    label: ComponentType
    /** The split's own value ΓÇö pass the unit inline if it needs one (this row has no separate `unit` prop). */
    value: string
    /** Colors this split's value by band; omit to keep it neutral foreground (e.g. a split that isn't itself good/bad). */
    band?: VerdictHeroBand
}

/** Props for the {@link VerdictHeroCard} block. */
export interface VerdictHeroCardProps {
    /** The headline number, rendered large and colored by {@link VerdictHeroCardProps.band}. */
    value: number
    /** Suffix rendered muted right after the value (e.g. "%", "/100"). */
    unit?: string
    /** Verdict tone ΓÇö see {@link VerdictHeroBand}. Drives the left accent border + value color + (when {@link VerdictHeroCardProps.meter} is set) the bar fill. */
    band: VerdictHeroBand
    /** The one-line judgment sentence (e.g. "You're overloaded ΓÇö adding new cards faster than you can retain them."). This is the "verdict" ΓÇö always render a real verdict, never a bare restatement of the number. */
    verdict: ReactNode
    /** Optional muted line under the verdict, giving the evidence behind it. */
    sub?: string
    /** Optional progress bar toward {@link VerdictHeroMeter.target}. Omit when the surface has no meaningful bar to show (e.g. a pure count). */
    meter?: VerdictHeroMeter
    /** Optional 2-up mini-stat row that breaks the headline number down (e.g. mature vs young retention) ΓÇö the "Γû╜" evidence framing. Omit when the number has no natural split. */
    splits?: ReadonlyArray<VerdictHeroSplit>
    /** Optional primary action slot (caller supplies the actual button) ΓÇö a buildable slot. */
    action?: ComponentType
}

/**
 * Same tone pairing the `Score` block hand-rolls for a band-colored number on a plain
 * (non-tinted) surface (`src/components/blocks/stats/Score/component.tsx`).
 *
 * MISSING VOCABULARY: no `Typography` atom `size` renders `text-4xl` (its scale stops at
 * `h1`, which wraps HeroUI's own proprietary heading treatment, not a raw `text-4xl`), so a
 * hero stat number can't go through the atom at all ΓÇö this is the SAME hand-rolled span the
 * `Score` block already carries for the identical reason, kept minimal and local here rather
 * than reopening a leaf's `className`.
 */
const BAND_TEXT: Record<VerdictHeroBand, string> = {
    danger: "text-danger-soft-foreground",
    warning: "text-warning-soft-foreground",
    success: "text-success-soft-foreground",
}

/**
 * `VerdictHeroSplit.band` ΓåÆ the closest {@link TypographyColor} the `Typography` atom exposes.
 *
 * MISSING VOCABULARY: `success` has an exact soft-foreground match (`"success-soft"`), but
 * `TypographyColor` has no `danger-soft` / `warning-soft` member (only `success-soft` and
 * `accent-soft` exist) ΓÇö those two bands fall back to the atom's full-strength tone instead of
 * the softer one `BAND_TEXT` uses for the headline value above.
 */
const SPLIT_VALUE_COLOR: Record<VerdictHeroBand, TypographyColor> = {
    danger: "danger",
    warning: "warning",
    success: "success-soft",
}

/**
 * The "verdict" (judgment) hero shared by all 3 Statistics surfaces (review /
 * interview / quiz): a band-colored headline value, a one-line verdict
 * sentence, an optional muted evidence sub-line, an optional
 * {@link ProgressMeter} with a target mark, an optional 2-up split
 * breakdown, and an optional primary action slot. Replaces the old "bare number"
 * hero ΓÇö every zone here reads verdict ΓåÆ evidence ΓåÆ action, never a number
 * alone (`stats-insight-redesign` proposal).
 *
 * No left accent band (2026-07-18 ΓÇö the teacher: drop the verdict band; the ┬º3i `SectionCard
 * withVerdict` band was dropped, the `band` prop now only colors the value / meter
 * / split values). The `splits` render as ONE surface-in-surface bordered row (rounded,
 * overflow-hidden, `SectionCard`'s own `bg-surface` shows through) with a full-height
 * divider between cells, `StackH`'s own `divider` (not a hand-rolled `border-l`).
 *
 * Pure/props-only ΓÇö no store, no fetch, no `useTranslations` (all copy
 * arrives via props from a caller that already translated it). No `className` (BLOCK-4):
 * nothing calls this with one today, and a per-call restyle belongs one tier down, named.
 *
 * @param props - {@link VerdictHeroCardProps}
 * @see Story: .storybook/stories/blocks/stats/VerdictHeroCard/VerdictHeroCard.stories
 */
export const VerdictHeroCard = ({
    value,
    unit,
    band,
    verdict,
    sub,
    meter,
    splits,
    action: Action,
}: VerdictHeroCardProps) => {
    const meterMax = meter?.max ?? 100

    return (
        <SectionCard identity={{ tier: "block", component: "VerdictHeroCard" }}>
            <StackH
                gap={3}
                principle="value-row"
                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                align="baseline"
                items={[
                    () => <span className={`text-4xl font-bold tabular-nums ${BAND_TEXT[band]}`}>{value}</span>,
                    ...(unit ? [() => <Typography size="sm" color="muted" text={unit} />] : []),
                ]}
            />

            <Typography size="sm" weight="semibold" text={verdict} />
            {sub ? (
                <Typography size="xs" color="muted" text={sub} />
            ) : null}

            {meter ? (
                <ProgressMeter
                    value={meter.value}
                    max={meterMax}
                    color={band}
                    target={meter.target}
                    targetLabel={meter.target === undefined ? undefined : `${meter.target}${unit ?? ""}`}
                />
            ) : null}

            {splits && splits.length > 0 ? (
                // Surface-in-surface: a bordered, rounded, clipped row sitting on top of
                // SectionCard's own bg-surface. `StackH`'s `divider` inserts a real (atom)
                // vertical rule between cells with `self-stretch`, so it reaches the full
                // height of the tallest cell ΓÇö the FRAME/atom equivalent of the old
                // hand-rolled `border-l` per cell past the first.
                <div className="overflow-hidden rounded-2xl border border-default">
                    <StackH
                        gap={1}
                        align="stretch"
                        divider
                        items={splits.map((split) => () => {
                            const SplitLabel = split.label
                            return (
                                // position-keyed: a fixed N-up breakdown of the SAME headline number,
                                // never reordered/filtered at runtime like a normal list.
                                <StackV
                                    gap={1}
                                    padding={4}
                                    principle="cell-pad"
                                    explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body."
                                    classNames={["flex-1"]}
                                    body={() => (
                                        <StackV
                                            gap={2}
                                            principle="title-subtitle"
                                            explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                                            items={[
                                                () => <Typography size="xs" color="muted" text={<SplitLabel />} />,
                                                () => (
                                                    <Typography
                                                        size="h4"
                                                        weight="bold"
                                                        color={split.band ? SPLIT_VALUE_COLOR[split.band] : undefined}
                                                        text={split.value}
                                                    />
                                                ),
                                            ]}
                                        />
                                    )}
                                />
                            )
                        })}
                    />
                </div>
            ) : null}

            {Action ? <div><Action /></div> : null}
        </SectionCard>
    )
}

