import { useAccountMenuOverlayState, useAuthenticationOverlayState } from "@/hooks/zustand/overlay/hooks"

/** Props for {@link AccountMenuGuest}. */
export type AccountMenuGuestProps = Record<string, never>
/**
 * Account dropdown menu for SIGNED-OUT viewers: sign in + sign up, each opening
 * the authentication modal on its tab. Self-contained ΓÇö dispatches the auth tab,
 * closes the menu, and opens the overlay; takes no data props.
 *
 * @param props - optional className (placement only).
 */
export const AccountMenuGuest = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const { close } = useAccountMenuOverlayState()
    const { open: openAuthentication } = useAuthenticationOverlayState()

    /** Open the auth modal on the chosen tab, then close this dropdown. */
    const onAuth = useCallback(
        (tab: AuthenticationModalTab) => {
            dispatch(setAuthenticationModalTab(tab))
            close()
            openAuthentication()
        },
        [dispatch, close, openAuthentication],
    )

    return (
        <Dropdown.Menu>
            <Dropdown.Section>
                <Dropdown.Item
                    id="sign-in"
                    textValue={t("auth.signIn.submit")}
                    onPress={() => onAuth(AuthenticationModalTab.SignIn)}
                >
                    <SignInIcon className="size-5" />
                    <Label>{t("auth.signIn.submit")}</Label>
                </Dropdown.Item>
                <Dropdown.Item
                    id="sign-up"
                    textValue={t("auth.signUp.submit")}
                    onPress={() => onAuth(AuthenticationModalTab.SignUp)}
                >
                    <UserPlusIcon className="size-5" />
                    <Label>{t("auth.signUp.submit")}</Label>
                </Dropdown.Item>
            </Dropdown.Section>
        </Dropdown.Menu>
    )
}

"use client"

import { UserIcon } from "@phosphor-icons/react"
import React, { useCallback } from "react"
import { Badge, Button } from "@heroui/react"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { useAppSelector } from "@/redux/hooks"
import { useAccountMenuOverlayState } from "@/hooks/zustand/overlay/hooks"

/**
 * Props for {@link AccountTrigger}.
 */
export type AccountTriggerProps = Record<string, never>
/**
 * Dropdown trigger button shown in the navbar.
 *
 * Container: reads auth state + user from Redux and opens the account-menu
 * overlay itself. Renders a generic user icon for guests or an avatar badge
 * for authenticated users.
 * `"use client"` for store selectors + press handler.
 * @param props - optional root class name
 */
export const AccountTrigger = () => {
    const isAuthenticated = useAppSelector((state) => state.keycloak.authenticated)
    const user = useAppSelector((state) => state.user.user)
    const { open } = useAccountMenuOverlayState()

    /** Open the account dropdown. */
    const onOpen = useCallback(() => open(), [open])

    if (!isAuthenticated) {
        return (
            <Button
                onPress={onOpen}
                isIconOnly
                className={"rounded-full"}
                variant="tertiary"
            >
                <UserIcon className="size-5" />
            </Button>
        )
    }
    return (
        <Button
            onPress={onOpen}
            isIconOnly
            className={"rounded-full"}
            variant="tertiary"
        >
            <Badge.Anchor>
                <UserAvatar
                    size="sm"
                    className="cursor-pointer"
                    username={user?.username}
                    avatar={user?.avatar}
                    seed={user?.email ?? user?.username}
                />
                <Badge size="sm" color="accent">5</Badge>
            </Badge.Anchor>
        </Button>
    )
}

"use client"

import React from "react"
import {
    Dropdown,
} from "@heroui/react"
import { AccountTrigger } from "./AccountTrigger"
import { UserSummary } from "./UserSummary"
import { GuestHeader } from "./GuestHeader"
import { AccountMenuAuthed } from "./AccountMenuAuthed"
import { AccountMenuGuest } from "./AccountMenuGuest"
import { useAccountMenuOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useQueryUserSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserSwr"
import { useAppSelector } from "@/redux/hooks"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Divider } from "@/components/atoms/display/Divider"
import { StackV } from "@/components/frames/Stack"

/**
 * AccountMenuDropdown ΓÇö navbar account menu. Two regions, both swapped on auth
 * state and both holding a placeholder while the shared `me` query first resolves:
 *   1. a STATIC header region ΓÇö UserSummary for signed-in viewers, GuestHeader
 *      for guests.
 *   2. a Dropdown.Menu ΓÇö AccountMenuAuthed (dashboard/profile/settings/sign-out)
 *      for signed-in viewers, AccountMenuGuest (sign in / sign up) for guests.
 * Language + theme live in the navbar itself, so they are not repeated here.
 *
 * Thin container: owns only the dropdown overlay state and the auth flags; each
 * region self-fetches/dispatches. `"use client"` for the hooks.
 *
 * `Dropdown` stays a raw HeroUI primitive: the atom layer wraps no dropdown yet,
 * and inventing one for a single call site is a bigger call than this pass makes.
 */
export const AccountMenuDropdown = () => {
    const { isOpen, setOpen } = useAccountMenuOverlayState()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const user = useAppSelector((state) => state.user.user)
    // real loading signal: the shared "me" query (deduped). On FAIL it resolves to
    // not-loading with no user ΓåÆ guest (the `initialized` flag is never set, so it
    // would shimmer forever). Placeholder only on first load with no user yet.
    const { isLoading } = useQueryUserSwr()
    const isSkeleton = isLoading && !user

    // authed view only when we actually have the user ΓÇö a dead/expired session or
    // any auth error falls back to guest (not a broken authed view / error state)
    const isAuthed = authenticated && Boolean(user)

    return (
        <Dropdown isOpen={isOpen} onOpenChange={setOpen}>
            <AccountTrigger />
            <Dropdown.Popover placement="bottom right" className="w-[300px]">
                {/* (1) static header region ΓÇö UserSummary / GuestHeader, shimmering as a UserCell */}
                <StackV
                    principle="cell-pad"
                    explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body."
                    body={() => (isSkeleton
                        ? <Skeleton.UserCell />
                        : isAuthed ? <UserSummary /> : <GuestHeader />)}
                />
                <Divider />
                {/* (2) menu ΓÇö authed actions / guest sign-in, shimmering as four rows */}
                {isSkeleton
                    ? <Skeleton.Menu items={4} />
                    : isAuthed ? <AccountMenuAuthed /> : <AccountMenuGuest />}
            </Dropdown.Popover>
        </Dropdown>
    )
}

"use client"

import React from "react"
import { Badge, Button } from "@heroui/react"
import { ShoppingCartIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useCart } from "@/hooks/useCart"
import { useCartEntry } from "@/hooks/useCartEntry"

/** Largest cart count rendered verbatim on the badge before showing "9+". */
const MAX_BADGE = 9

/**
 * Props for {@link CartButton}.
 */
export type CartButtonProps = Record<string, never>
/**
 * Navbar shopping-cart button: a tertiary icon button ALWAYS shown (guests included,
 * so the cart is discoverable) with an accent count badge only when the cart is
 * non-empty. Tapping opens the mini-cart drawer for a signed-in viewer, or the
 * authentication modal for a guest (remembering the "open cart" intent to replay
 * after sign-in). Reads {@link useCart} + {@link useCartEntry} directly (no props).
 * @param props - optional root class name (placement only)
 */
export const CartButton = () => {
    const t = useTranslations()
    const { count } = useCart()
    const { openCartOrAuth } = useCartEntry()

    /** Badge label, capped at {@link MAX_BADGE} (e.g. "9+"). */
    const badgeLabel = count > MAX_BADGE ? `${MAX_BADGE}+` : `${count}`

    return (
        <Button
            isIconOnly
            variant="tertiary"
            className={"rounded-full"}
            aria-label={t("cart.title")}
            onPress={openCartOrAuth}
        >
            {count > 0 ? (
                <Badge.Anchor>
                    <ShoppingCartIcon className="size-5" />
                    <Badge size="sm" color="accent">{badgeLabel}</Badge>
                </Badge.Anchor>
            ) : (
                <ShoppingCartIcon className="size-5" />
            )}
        </Button>
    )
}

"use client"

import React from "react"
import { TranslateIcon } from "@phosphor-icons/react"
import type { Selection } from "@heroui/react"
import {
    Button,
    Dropdown,
    Label,
} from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import { usePathname, useRouter } from "@/i18n/navigation"
import { languages } from "@/resources/constants/lang"

/**
 * Props for {@link LanguageDropdown}.
 */
export type LanguageDropdownProps = Record<string, never>
/**
 * Standalone language switcher for the navbar ΓÇö a globe-icon dropdown listing the
 * available locales with a single-selection check (Dropdown.ItemIndicator) on the
 * active one. Pulled OUT of the account menu so switching language is a
 * first-class, one-tap action. Self-contained: reads the active locale and
 * self-navigates to the same path under the chosen locale via the i18n router.
 *
 * @param props - optional root class name (placement only)
 */
export const LanguageDropdown = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()

    /** Switch to the picked locale (same path) when the selection changes. */
    const onSelectionChange = (keys: Selection) => {
        if (keys === "all") return
        const next = [...keys][0]
        if (next && String(next) !== locale) {
            router.replace(pathname, { locale: String(next) })
        }
    }

    return (
        <Dropdown>
            <Button
                isIconOnly
                variant="tertiary"
                aria-label={t("nav.toggleLanguage")}
            >
                <TranslateIcon className="size-5" />
            </Button>
            <Dropdown.Popover>
                <Dropdown.Menu
                    selectionMode="single"
                    selectedKeys={new Set([locale])}
                    onSelectionChange={onSelectionChange}
                >
                    <Dropdown.Section>
                        {languages.map((language) => (
                            <Dropdown.Item
                                key={language.code}
                                id={language.code}
                                textValue={language.label}
                            >
                                <Dropdown.ItemIndicator />
                                <Label>{language.label}</Label>
                            </Dropdown.Item>
                        ))}
                    </Dropdown.Section>
                </Dropdown.Menu>
            </Dropdown.Popover>
        </Dropdown>
    )
}

