"use client"

import {
    BellIcon,
    ChecksIcon as CheckDoubleIcon,
    CircleIcon,
} from "@phosphor-icons/react"
import React, {
    useCallback,
    useMemo,
    useState,
} from "react"
import { Badge, Button, Header, Popover, PopoverContent, Typography } from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import { mutateMarkAllNotificationsAsRead } from "@/modules/api/graphql/mutations/mutation-mark-all-notifications-as-read"
import { mutateMarkNotificationAsRead } from "@/modules/api/graphql/mutations/mutation-mark-notification-as-read"
import type { QueryNotificationData } from "@/modules/api/graphql/queries/types/notifications"
import { resolveNotificationTargetPath } from "@/modules/notifications/resolve-notification-target"
import { useQueryMyNotificationsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyNotificationsSwr"
import { useAppSelector } from "@/redux/hooks"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { ListRow } from "@/components/blocks/lists/ListRow"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { pathConfig } from "@/resources/path"

/** Largest unread count rendered verbatim on the badge before showing "9+". */
const MAX_BADGE = 9

/** Props for {@link NotificationBell}. */
export type NotificationBellProps = Record<string, never>
/**
 * NotificationBell ΓÇö navbar bell with an unread-count badge and a popover list.
 *
 * Self-contained container: fetches its own notification page (newest first) +
 * unread count, renders the badge (hidden when zero), and on open shows the
 * recent items (via the {@link ListRow} block) with an i18n title and relative
 * time. Clicking an item marks it read and routes to its resolved target; the
 * header action marks all read. `"use client"` for the SWR hook, popover state
 * and navigation.
 * @param props - optional root class name (placement only)
 */
export const NotificationBell = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const { data, isLoading, error, mutate } = useQueryMyNotificationsSwr()
    const runGraphQL = useGraphQLWithToast()
    const [isOpen, setOpen] = useState(false)

    const items = data?.items ?? []
    const unreadCount = data?.unreadCount ?? 0

    /** Locale-aware relative-time formatter for the item timestamps. */
    const relativeFormat = useMemo(
        () => new Intl.RelativeTimeFormat(locale, { numeric: "auto" }),
        [locale],
    )

    /** Format an ISO timestamp as a coarse relative string ("3h ago"). */
    const formatRelative = useCallback(
        (iso: string): string => {
            const diffMs = new Date(iso).getTime() - Date.now()
            const diffMin = Math.round(diffMs / 60_000)
            const absMin = Math.abs(diffMin)
            if (absMin < 60) {
                return relativeFormat.format(diffMin, "minute")
            }
            const diffHour = Math.round(diffMin / 60)
            if (Math.abs(diffHour) < 24) {
                return relativeFormat.format(diffHour, "hour")
            }
            const diffDay = Math.round(diffHour / 24)
            return relativeFormat.format(diffDay, "day")
        },
        [relativeFormat],
    )

    /** Mark a single notification read and navigate to its resolved target. */
    const onPressItem = useCallback(
        async (notification: QueryNotificationData) => {
            setOpen(false)
            // optimistically mark read in the local cache, then persist
            if (!notification.isRead) {
                await runGraphQL(
                    async () => {
                        const env = await mutateMarkNotificationAsRead({
                            request: { notificationId: notification.id },
                        })
                        return env.data!.markNotificationAsRead
                    },
                    { showSuccessToast: false, showErrorToast: false },
                )
                await mutate()
            }
            // resolve the snapshotted target into a route, then push to it
            const { target } = notification
            if (!target) {
                return
            }
            const path = await resolveNotificationTargetPath(target)
            if (path) {
                router.push(`/${locale}${path}`)
            }
        },
        [locale, mutate, router, runGraphQL],
    )

    /** Mark every unread notification read in one bulk action. */
    const onMarkAllRead = useCallback(
        async () => {
            await runGraphQL(
                async () => {
                    const env = await mutateMarkAllNotificationsAsRead({
                        request: undefined,
                    })
                    return env.data!.markAllNotificationsAsRead
                },
                { showSuccessToast: false, showErrorToast: true },
            )
            await mutate()
        },
        [mutate, runGraphQL],
    )

    // the bell is only meaningful for an authenticated viewer
    if (!authenticated) {
        return null
    }

    /** Badge label, capped at {@link MAX_BADGE} (e.g. "9+"). */
    const badgeLabel = unreadCount > MAX_BADGE ? `${MAX_BADGE}+` : `${unreadCount}`

    return (
        <Popover isOpen={isOpen} onOpenChange={setOpen}>
            <Button
                isIconOnly
                variant="tertiary"
                className={"rounded-full"}
                aria-label={t("notifications.title")}
            >
                {unreadCount > 0 ? (
                    <Badge.Anchor>
                        <BellIcon className="size-5" />
                        <Badge size="sm" color="danger">{badgeLabel}</Badge>
                    </Badge.Anchor>
                ) : (
                    <BellIcon className="size-5" />
                )}
            </Button>
            <PopoverContent placement="bottom right" className="w-[360px]">
                <div className="py-1 px-2">
                    {/* header: title + bulk "mark all read" action */}
                    <div className="flex items-center justify-between gap-3">
                    
                        <Header>{t("notifications.title")}</Header>
                        {unreadCount > 0 ? (
                            <Button
                                isIconOnly
                                variant="ghost"
                                size="sm"
                                aria-label={t("notifications.markAllRead")}
                                onPress={onMarkAllRead}
                            >
                                <CheckDoubleIcon className="size-5" />
                            </Button>
                        ) : null}
                    </div>
                    {/* body: async switch ΓÇö skeleton MIRRORS the list (debug holds 3s) */}
                    <AsyncContent
                        isLoading={isLoading && items.length === 0}
                        skeleton={(
                            <div className="flex flex-col">
                                {[0, 1, 2].map((row) => (
                                    <Skeleton.ListRow key={row} />
                                ))}
                            </div>
                        )}
                        isEmpty={items.length === 0}
                        emptyContent={{
                            title: t("notifications.empty"),
                        }}
                        error={error}
                        errorContent={{
                            title: t("notifications.loadError"),
                            onRetry: () => { void mutate() },
                            retryLabel: t("notifications.retry"),
                        }}
                    >
                        <div className="flex max-h-[420px] flex-col overflow-y-auto">
                            {items.map((notification, index) => (
                                <ListRow
                                    key={notification.id}
                                    leading={!notification.isRead ? (
                                        <CircleIcon
                                            weight="fill"
                                            aria-hidden
                                            focusable="false"
                                            className="size-2 text-accent-soft-foreground"
                                        />
                                    ) : undefined}
                                    title={t(
                                        notification.title.key,
                                        notification.title.params ?? undefined,
                                    )}
                                    subtitle={notification.body
                                        ? t(
                                            notification.body.key,
                                            notification.body.params ?? undefined,
                                        )
                                        : undefined}
                                    meta={(
                                        <Typography type="body-xs" color="muted">
                                            {formatRelative(notification.createdAt)}
                                        </Typography>
                                    )}
                                    onPress={() => onPressItem(notification)}
                                    divider={index < items.length - 1}
                                />
                            ))}
                        </div>
                    </AsyncContent>
                    {/* footer: deep-link to the full notification center (all types +
                        pager) ΓÇö the bell only ever shows the most recent page. */}
                    <Button
                        variant="ghost"
                        size="sm"
                        className="mt-1 w-full"
                        onPress={() => {
                            setOpen(false)
                            router.push(pathConfig().locale(locale).notifications().build())
                        }}
                    >
                        {t("notifications.seeAll")}
                    </Button>
                </div>
            </PopoverContent>
        </Popover>
    )
}

"use client"

import { MagnifyingGlassIcon } from "@phosphor-icons/react"
import React from "react"
import {
    Kbd,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import { useSearchOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useIsMacPlatform } from "@/hooks/useIsMacPlatform"
import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"

/**
 * Props for {@link SearchButton}.
 */

/**
 * Navbar search trigger ΓÇö looks like a native input field (via the
 * {@link InputButtonLike} block) but opens the search overlay on press. Shows
 * the search label and the Ctrl/Cmd+K shortcut hint.
 *
 * Self-contained section (single-use): reads the search overlay singleton itself
 * and opens it on press. `"use client"` for the singleton hook + press handler.
 */
export const SearchButton = () => {
    const t = useTranslations()
    const { open: onOpenSearch } = useSearchOverlayState()
    const isMac = useIsMacPlatform()
    return (
        <InputButtonLike
            onPress={onOpenSearch}
            placeholder={t("search.label")}
            icon={MagnifyingGlassIcon}
            suffix={() => (
                // one combined Kbd chip (per HeroUI docs ΓÇö a shortcut combo is a single
                // Kbd wrapping its parts, not one chip per key); the modifier is
                // OS-adaptive: Γîÿ (Kbd.Abbr) on Mac, the word "Ctrl" everywhere else
                // (HeroUI's `keyValue="ctrl"` renders the Mac Control glyph Γîâ, wrong here)
                <Kbd>
                    {isMac ? <Kbd.Abbr keyValue="command" /> : <Kbd.Content>Ctrl</Kbd.Content>}
                    <Kbd.Content>K</Kbd.Content>
                </Kbd>
            )}
        />
    )
}

"use client"

import { Box } from "@/components/frames/Box"
import React, {
    useEffect,
    useState,
} from "react"
import { Button, Drawer, Typography } from "@heroui/react"
import {
    SidebarSimpleIcon as MenuIcon,
    MagnifyingGlassIcon as SearchIcon,
} from "@phosphor-icons/react"
import {
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "@/i18n/navigation"
import {
    useNavbarItems,
} from "./useNavbarItems"
import {
    Logo,
} from "./Logo"
import {
    AccountMenuDropdown,
} from "./AccountMenuDropdown"
import {
    NavLinks,
} from "./NavLinks"
import {
    SearchButton,
} from "./SearchButton"
import {
    NotificationBell,
} from "./NotificationBell"
import {
    CartButton,
} from "./CartButton"
import {
    LanguageDropdown,
} from "./LanguageDropdown"
import {
    DarkLightModeSwitch,
} from "./AccountMenuDropdown/DarkLightModeSwitch"
import { useNavbarBottomLayerStore } from "@/hooks/zustand/navbarBottomLayer/store"
import { useSearchOverlayState } from "@/hooks/zustand/overlay/hooks"

/**
 * Props for {@link Navbar}.
 */
export type NavbarProps = Record<string, never>
/**
 * Navbar ΓÇö top application navigation bar.
 *
 * Container: owns the Ctrl/Cmd+K search shortcut + the mobile drawer state and
 * composes the logo, nav links, search trigger (full field on desktop, icon on
 * mobile), the standalone language dropdown, the theme switch, notifications,
 * the account menu, and a mobile expand button that opens a navigation drawer.
 * `"use client"` for hooks + keyboard handling.
 * @param props - optional root class name (placement only)
 */
export const Navbar = () => {
    const t = useTranslations()
    const router = useRouter()
    const { open: openSearch } = useSearchOverlayState()
    const [isDrawerOpen, setDrawerOpen] = useState(false)
    // optional second layer (e.g. profile tabs) a page registered into the navbar
    const bottomLayer = useNavbarBottomLayerStore((state) => state.bottomLayer)

    // register the global Ctrl/Cmd+K shortcut to open the search overlay
    useEffect(() => {
        const onKeyDown = (event: KeyboardEvent) => {
            // some keydown events (IME composition, autofill) fire with no `key`
            const isK = event.key?.toLowerCase() === "k"
            if (!isK) return
            if (!(event.ctrlKey || event.metaKey)) return
            event.preventDefault()
            openSearch()
        }
        window.addEventListener("keydown", onKeyDown)
        return () => window.removeEventListener("keydown", onKeyDown)
    }, [openSearch])

    // mobile drawer nav entries (same source of truth as desktop NavLinks, plus cart)
    const mobileNavItems = useNavbarItems({ includeCart: true })

    return (
        <nav className={"sticky top-0 z-50 border-b border-separator bg-background"}>
            {/* primary row ΓÇö fixed 4rem tall; the nav root owns the single bottom border */}
            <div className="flex h-16 min-h-16 w-full items-center justify-between gap-3 px-3">
                <div className="flex items-center gap-6">
                    <Logo className="justify-start" />
                    <NavLinks />
                </div>

                <div className="flex items-center justify-end gap-2">
                    {/* desktop: full input-style search; mobile: just an icon */}
                    {/* the search field is the navbar's own placement call ΓÇö a fixed measure that
                        only appears once there is room for it */}
                    <Box className="hidden w-[260px] @app-md:flex">
                        <SearchButton />
                    </Box>
                    <Button
                        isIconOnly
                        variant="tertiary"
                        aria-label={t("search.label")}
                        className="@app-md:hidden"
                        onPress={openSearch}
                    >
                        <SearchIcon className="size-5" />
                    </Button>
                    {/* desktop: language + theme inline; on mobile they move into the drawer */}
                    <div className="hidden items-center gap-2 @app-md:flex">
                        <LanguageDropdown />
                        <DarkLightModeSwitch />
                    </div>
                    <CartButton />
                    <NotificationBell />
                    <AccountMenuDropdown />
                    {/* mobile: expand icon ΓåÆ navigation drawer */}
                    <Button
                        isIconOnly
                        variant="ghost"
                        aria-label={t("nav.mobileMenu")}
                        className="@app-md:hidden"
                        onPress={() => setDrawerOpen(true)}
                    >
                        <MenuIcon className="size-5" />
                    </Button>
                </div>
            </div>

            {/* page-registered secondary layer (e.g. profile tabs). It sits flush
                under the primary row with NO divider of its own ΓÇö the nav root's
                single border-b falls under whichever layer is last (single ΓåÆ row,
                bottomLayer ΓåÆ this), so there is always exactly one navbar border. */}
            {bottomLayer ? <div className="w-full">{bottomLayer}</div> : null}

            {/* mobile navigation drawer (opened by the expand icon) */}
            <Drawer>
                <Drawer.Backdrop isOpen={isDrawerOpen} onOpenChange={setDrawerOpen}>
                    <Drawer.Content placement="right">
                        <Drawer.Dialog className="flex h-full flex-col">
                            <Drawer.CloseTrigger />
                            <Drawer.Header>
                                <Drawer.Heading>{t("nav.mobileMenu")}</Drawer.Heading>
                            </Drawer.Header>
                            <Drawer.Body className="flex flex-col gap-6">
                                <div className="flex flex-col gap-2">
                                    {mobileNavItems.map((item) => (
                                        <Button
                                            key={item.path}
                                            variant={item.isActive ? "secondary" : "ghost"}
                                            fullWidth
                                            className="justify-start"
                                            onPress={() => {
                                                router.push(item.path)
                                                setDrawerOpen(false)
                                            }}
                                        >
                                            {item.label}
                                        </Button>
                                    ))}
                                </div>
                                {/* controls hidden from the mobile bar live here: language + theme */}
                                <div className="flex flex-col gap-3">
                                    <div className="flex items-center justify-between gap-3">
                                        <Typography type="body-sm">
                                            {t("nav.toggleLanguage")}
                                        </Typography>
                                        <LanguageDropdown />
                                    </div>
                                    <div className="flex items-center justify-between gap-3">
                                        <Typography type="body-sm">
                                            {t("nav.appearance")}
                                        </Typography>
                                        <DarkLightModeSwitch />
                                    </div>
                                </div>
                            </Drawer.Body>
                        </Drawer.Dialog>
                    </Drawer.Content>
                </Drawer.Backdrop>
            </Drawer>
        </nav>
    )
}

import React from "react"
import {
    PersonalProjectDashboard,
    type PersonalProjectDashboardProps,
} from "@/components/blocks/learn/PersonalProjectDashboard"
import {
    PersonalProjectTaskPage,
    type PersonalProjectTaskPageProps,
} from "@/components/pages/PersonalProjectTaskPage"
import {
    PersonalProjectResultScreen,
    type PersonalProjectResultScreenProps,
} from "@/components/blocks/learn/PersonalProjectResultScreen"

/**
 * `_PersonalProjectWorkspaceLayout` ΓÇö the SRC TWIN of `.storybook/components/starci/
 * pages/PersonalProjectWorkspace/PersonalProjectWorkspace.tsx`. Presentational:
 * typed props, already resolved; no fetch/store/i18n (that's the connected half,
 * `./index.tsx`).
 *
 * SCREEN ΓÇö the personal-project route group's own content switch. See the
 * blueprint's file header for the full RULE 12 investigation (why this is a
 * `pages/` screen, not a `layouts/` wrapper) and for why this file is a thin
 * dispatch rather than a rebuild of any content.
 *
 * THREE LEAVES, one per `view` ΓÇö a STRUCTURAL fork (which of three disjoint
 * screens mounts), not a data state of one shape: `Dashboard` (`/personal-
 * project`), `Task` (`/personal-project/tasks/[taskId]`), `Result`
 * (`ΓÇª/result`). Each leaf hands the real, untouched prop surface of the screen
 * it dispatches to straight through ΓÇö this file invents no data shape of its
 * own. Each leaf renders the CONNECTED child export (`PersonalProjectDashboard`,
 * `PersonalProjectTaskPage`, `PersonalProjectResultScreen`), which in these twins
 * happen to be presentational (the children own no data of their own).
 */

/** Props for {@link _PersonalProjectWorkspaceLayout} ΓÇö see the file header for the `view` split. */
export type PersonalProjectWorkspaceLayoutProps =
    | ({ view: "dashboard" } & PersonalProjectDashboardProps)
    | ({ view: "task" } & PersonalProjectTaskPageProps)
    | ({ view: "result" } & PersonalProjectResultScreenProps)

/**
 * The personal-project route group's content switch. See the file header for
 * why this screen exists and why it owns none of its own DOM.
 *
 * @param props - {@link PersonalProjectWorkspaceLayoutProps}
 */
const _PersonalProjectWorkspaceLayout = (props: PersonalProjectWorkspaceLayoutProps) => {
    // No wrapper div (BLOCK-2): each of the three leaves below is this
    // screen's own root for the branch it renders. None of the three yet
    // accepts the `identity` prop from `_identity.ts` (`PersonalProjectDashboard`,
    // `PersonalProjectTaskPage`, `PersonalProjectResultScreen` all still draw
    // their OWN `data-tier="block"`/`"page"` on their own root) and none is
    // wrapped in a sibling frame here to carry this screen's identity instead
    // ΓÇö so this screen currently renders with no `data-tier="page"
    // data-component="PersonalProjectWorkspace"` node of its own anywhere in
    // the tree, rather than re-adding the raw div BLOCK-2 forbids.
    if (props.view === "dashboard") return <PersonalProjectDashboard {...props} />
    if (props.view === "task") return <PersonalProjectTaskPage {...props} />
    return <PersonalProjectResultScreen {...props} />
}

export { _PersonalProjectWorkspaceLayout }

import React, { useEffect, useMemo, useState } from "react"
import { ArrowRightIcon, ShoppingCartIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { Container } from "@/components/frames/Container"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { CartLine } from "@/components/blocks/commerce/CartLine"
import { publicEnv } from "@/resources/env/public"
import type { CartItemEntity } from "@/modules/api/graphql/queries/types/my-cart"
import type { CoursesCheckoutPreviewLine } from "@/modules/api/graphql/queries/types/courses-checkout-preview"
import type { CourseEntity } from "@/modules/types/entities/course"

/** How many placeholder rows the co-located skeleton shows for the cart-line list. */
const SKELETON_ROW_COUNT = 3

/** Format an integer VND amount as "1.275.000Γé½". */
export const formatVnd = (amount: number): string => `${amount.toLocaleString("vi-VN")}Γé½`

/**
 * A course's DISPLAY list VND price from its entity (active-phase price, falling
 * back to the list price, ├╖ non-prod test divisor). Used only as the FALLBACK
 * total when the checkout preview fails ΓÇö the real charged total comes from the
 * preview, whose amounts are already display-ready.
 */
const displayPriceVnd = (course: CourseEntity): number => {
    const divisor = publicEnv().pricing.testDivisor
    const toVnd = (amount: number): number =>
        divisor === 1 ? amount : Math.max(1, Math.round(amount / divisor))
    const phasePrice = course.pricingPhases?.find(
        (phase) => phase.phase === course.currentPhase,
    )?.price
    return toVnd(phasePrice ?? course.originalPrice ?? 0)
}

/**
 * One row's minimal shimmer standing in for {@link CartLine} while the cart's
 * first load is in flight. `CartLine` takes no `isSkeleton` prop, so this mirrors
 * its leading-tile + title/price + trailing-button shape as a `content` slot
 * inside {@link SurfaceCardList} (Decision C ΓÇö same tree, no parallel list).
 */
const CartLineSkeletonBody = () => (
    <StackH gap={4} items={[
        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
        () => (
            <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[
                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                () => <Skeleton className="h-4 w-24 rounded-lg" />,
            ]} />
        ),
        () => <Skeleton className="size-9 shrink-0 rounded-lg" />,
    ]} />
)

/** Props for the private {@link ClearCartButton} helper. */
interface ClearCartButtonProps {
    isDisabled: boolean
    onClear: () => void
    /** Already-translated resting label ("Clear cart"). */
    clearLabel: string
    /** Already-translated armed-state label ("Press again to confirm"). */
    confirmLabel: string
}

/**
 * "Clear cart" with a lightweight inline 2-step confirm (no modal): first press
 * arms a danger-soft "confirm" state that auto-disarms after 3s; second press
 * within the window actually clears ΓÇö so a destroy-all action can't fire on one
 * stray click. (canon: destructive action needs confirmation.)
 */
const ClearCartButton = ({ isDisabled, onClear, clearLabel, confirmLabel }: ClearCartButtonProps) => {
    const [confirming, setConfirming] = useState(false)
    useEffect(() => {
        if (!confirming) return
        const timer = setTimeout(() => setConfirming(false), 3000)
        return () => clearTimeout(timer)
    }, [confirming])
    return (
        <Button
            variant={confirming ? "danger-soft" : "tertiary"}
            isDisabled={isDisabled}
            label={confirming ? confirmLabel : clearLabel}
            classNames={["w-full"]}
            onPress={() => {
                if (confirming) {
                    onClear()
                    setConfirming(false)
                } else {
                    setConfirming(true)
                }
            }}
        />
    )
}

/** All display text, already localized by the connected `CartPage`; a story passes i18n keys. */
export interface CartPageLabels {
    title: string
    description: string
    empty: string
    emptyHint: string
    browseCourses: string
    error: string
    retry: string
    total: string
    /** Full "Checkout (N)" sentence ΓÇö the connected file interpolates the count. */
    checkoutCount: string
    clear: string
    clearConfirm: string
    /** Present only when the preview reports a real saving over the list total. */
    savings?: string
    /** Present only when the preview also reports a multi-course bundle bonus. */
    bundleBonus?: string
    /** Present only when an installment plan exists for this cart. */
    installmentHint?: string
    /** "Add one more to unlock the next tier" nudge ΓÇö present only at cart size 1 or 2. */
    addMoreHint?: string
}

/** Props for {@link _CartPage} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface CartPageProps {
    /** Every cart row with its full course. */
    items: Array<CartItemEntity>
    /** The checkout preview's per-course lines, for per-line pricing inside {@link CartLine}. */
    previewLines: Array<CoursesCheckoutPreviewLine>
    /** Real charged total from the checkout preview; undefined while it's pending or on error. */
    totalChargedVnd?: number
    /** Real list (pre-discount) total from the checkout preview. */
    totalListVnd?: number
    /** Disables the remove/checkout/clear affordances while a cart write is in flight. */
    isMutating: boolean
    /** First load, nothing in hand yet ΓåÆ the cart-line list + footer shimmer in place. */
    isSkeleton?: boolean
    /** Settled with zero rows ΓåÆ the empty message (offers browsing courses). */
    isEmpty?: boolean
    /** Truthy ΓåÆ the error message (beats loading + empty). The connected file's settled cart-fetch error. */
    error?: unknown
    /**
     * The cart itself has resolved but the checkout-preview query (a separate SWR
     * key) is still pending ΓÇö only the footer total/savings block shimmers.
     */
    isPreviewSkeleton?: boolean
    /** Retry handler for the error branch ΓÇö re-fetches the cart. */
    onRetry: () => void
    /** Remove one course from the cart. */
    onRemove: (courseId: string) => void
    /** Opens the payment overlay for the current cart. */
    onCheckout: () => void
    /** Empties the cart (after the inline 2-step confirm). */
    onClearCart: () => void
    /** Jumps to course browsing ΓÇö the empty state's action. */
    onBrowseCourses: () => void
    labels: CartPageLabels
}

/**
 * Shopping-cart page ΓÇö the presentational half of {@link import("./index").CartPage}.
 * Header (always shown) ΓåÆ error/empty/content in that order (`error` beats a stale
 * `isSkeleton`; `isEmpty` only once settled) ΓåÆ cart lines in one `SurfaceCardList` ΓåÆ
 * a footer with the REAL discounted total (progressive loyalty + multi-course bundle
 * bonus), the saving, a bundle chip, an "add more to save more" nudge, a primary
 * "Checkout" CTA (opens the payment modal), and a tertiary "Clear cart". The cart-line
 * list and the footer's preview total shimmer independently (two separate SWR keys ΓÇö
 * `isSkeleton` for the cart itself, `isPreviewSkeleton` for the checkout preview),
 * both threaded co-located rather than built as a parallel skeleton tree. See
 * `tiers/split.md` ΓÇö the connected `./index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link CartPageProps}
 */
export const _CartPage = ({
    items,
    previewLines,
    totalChargedVnd,
    totalListVnd,
    isMutating,
    isSkeleton = false,
    isEmpty = false,
    error,
    isPreviewSkeleton = false,
    onRetry,
    onRemove,
    onCheckout,
    onClearCart,
    onBrowseCourses,
    labels,
}: CartPageProps) => {
    const { savings: savingsLabel, bundleBonus: bundleBonusLabel, installmentHint: installmentHintLabel, addMoreHint: addMoreHintLabel } = labels

    // courseId ΓåÆ preview line, for per-line pricing.
    const previewByCourse = useMemo(() => {
        const map = new Map<string, CoursesCheckoutPreviewLine>()
        previewLines.forEach((line) => map.set(line.courseId, line))
        return map
    }, [previewLines])

    // plain summed list total from the cart entities ΓÇö the fallback shown when the
    // preview total hasn't arrived (still pending, or errored).
    const fallbackTotalVnd = useMemo(
        () => items.reduce((sum, item) => sum + displayPriceVnd(item.course), 0),
        [items],
    )

    // the footer summary block: total (real charged) + savings + bundle chip + nudge.
    // While the preview itself is pending it shimmers independently of the cart list.
    const summaryItems = isPreviewSkeleton
        ? [() => <Skeleton className="h-4 w-40 rounded-lg" />]
        : [
            ...(savingsLabel ? [() => (
                <StackH gap={3} principle="flex-action" justify="between"
                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                    items={[
                        () => <Typography size="sm" color="success-soft" text={savingsLabel} />,
                        () => (bundleBonusLabel ? <Chip tone="accent" text={bundleBonusLabel} /> : null),
                    ]} />
            )] : []),
            ...(installmentHintLabel ? [() => <Typography size="xs" color="muted" text={installmentHintLabel} />] : []),
            ...(addMoreHintLabel ? [() => <Typography size="xs" color="muted" text={addMoreHintLabel} />] : []),
        ]

    // error beats a stale isSkeleton flag; empty only once settled (BLOCK-8) ΓÇö the
    // two message branches are the shared `AsyncContent*` frames, not hand-written JSX.
    const contentBody = () => {
        if (error) {
            return <AsyncContentError title={labels.error} onRetry={onRetry} retryLabel={labels.retry} />
        }
        if (!isSkeleton && isEmpty) {
            return (
                <AsyncContentEmpty
                    icon={ShoppingCartIcon}
                    title={labels.empty}
                    description={labels.emptyHint}
                    onRetry={onBrowseCourses}
                    retryLabel={labels.browseCourses}
                />
            )
        }
        return (
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => {
                        const listItems: Array<SurfaceCardListItem> = isSkeleton
                            ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
                                key: `skeleton-${index}`,
                                content: () => <CartLineSkeletonBody />,
                            }))
                            : items.map((item) => ({
                                key: item.id,
                                content: () => (
                                    <CartLine
                                        item={item}
                                        previewLine={previewByCourse.get(item.courseId)}
                                        onRemove={onRemove}
                                        isMutating={isMutating}
                                    />
                                ),
                            }))
                        return (
                            <SurfaceCardList
                                items={listItems}
                                isSkeleton={isSkeleton}
                            />
                        )
                    },
                    () => {
                    // Items hoisted so this gap-only column is not scanned as owning nested
                    // justify/principle from its children (check-pattern-coverage opens to `>`).
                        const footerColumnItems = isSkeleton
                            ? [() => <Skeleton className="h-12 w-full rounded-2xl" />]
                            : [
                                () => (
                                    <StackV gap={3} principle="sibling-stack" isSkeleton={isPreviewSkeleton}
                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => (
                                                <StackH gap={4} principle="content-row" justify="between"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => <Typography size="base" weight="semibold" text={labels.total} isSkeleton={isPreviewSkeleton} />,
                                                        () => (isPreviewSkeleton
                                                            ? <Skeleton className="h-7 w-32 rounded-lg" />
                                                            : (totalChargedVnd != null
                                                                ? (
                                                                    <PriceTagInline
                                                                        discounted={totalChargedVnd}
                                                                        original={totalListVnd}
                                                                        currency="VND"
                                                                    />
                                                                )
                                                                : <Typography size="h4" weight="bold" text={formatVnd(fallbackTotalVnd)} />)),
                                                    ]} />
                                            ),
                                            ...summaryItems,
                                        ]} />
                                ),
                                () => (
                                    <Button
                                        variant="primary"
                                        size="lg"
                                        isDisabled={isMutating}
                                        onPress={onCheckout}
                                        label={labels.checkoutCount}
                                        suffixIcon={ArrowRightIcon}
                                        classNames={["w-full"]}
                                    />
                                ),
                                () => (
                                    <ClearCartButton
                                        isDisabled={isMutating}
                                        onClear={onClearCart}
                                        clearLabel={labels.clear}
                                        confirmLabel={labels.clearConfirm}
                                    />
                                ),
                            ]
                        return <StackV gap={4} items={footerColumnItems} />
                    },
                ]} />
        )
    }

    return (
        <Container
            size="md"
            padding={6}
            identity={{ tier: "block", component: "CartPage" }}
            body={() => (
                <StackV gap={7} items={[
                    () => <PageHeader title={labels.title} description={labels.description} />,
                    contentBody,
                ]} />
            )}
        />
    )
}

"use client"

import React from "react"
import useSWR from "swr"
import { useTranslations } from "next-intl"
import { useAppSelector } from "@/redux/hooks"
import { queryCodingLeaderboard } from "@/modules/api/graphql/queries/query-coding-leaderboard"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { StackH } from "@/components/frames/Stack"

/** Max ranked users to pull for the board (backend caps this too). */
const LEADERBOARD_LIMIT = 50

/** Placeholder rows shown while the board loads. */
const SKELETON_ROWS = 6

/** One ranked entry as returned by `codingLeaderboard`. */
interface LeaderboardEntry {
    userId: string
    username: string
    solvedCount: number
}

/** Props for {@link LeaderboardRow}. */
interface LeaderboardRowProps {
    /** 1-based position on the board. */
    rank: number
    /** The ranked user. Absent only while {@link LeaderboardRowProps.isSkeleton}. */
    entry?: LeaderboardEntry
    /** Tints the signed-in viewer's own row. */
    isViewer?: boolean
    /** Already-translated "N solved" metric. */
    solvedLabel?: string
    /** Already-translated "you" chip label. */
    youLabel?: string
    /** First load ΓåÆ this row rests. Its resting state lives here, beside the loaded one. */
    isSkeleton?: boolean
}

/**
 * One board row: rank ┬╖ avatar + name ┬╖ the solved metric. ONE description of the
 * shape, resting or loaded, so the two cannot drift (`loading-and-skeleton.md`).
 *
 * @param props - {@link LeaderboardRowProps}
 */
const LeaderboardRow = ({ rank, entry, isViewer = false, solvedLabel, youLabel, isSkeleton = false }: LeaderboardRowProps) => (
    <Box className={!isSkeleton && isViewer ? "-m-3 bg-accent-soft p-3" : undefined}>
        <StackH
            gap={4}
            align="center"
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                // the rank column is a fixed gutter so every name starts on the same line
                () => (
                    <Box className="w-6 shrink-0">
                        <Typography
                            size="sm"
                            weight="semibold"
                            color="muted"
                            align="center"
                            isSkeleton={isSkeleton}
                            text={String(rank)}
                        />
                    </Box>
                ),
                () => (isSkeleton
                    ? <Skeleton.Avatar size="sm" />
                    : (
                        <FillAvailable
                            at="base"
                            explain="Name cell takes remaining row width beside rank and metric ΓÇö not a fixed peer column."
                            body={() => (
                                <UserCell
                                    username={entry?.username ?? ""}
                                    size="sm"
                                    trailing={isViewer ? () => <Chip tone="accent" text={youLabel} /> : undefined}
                                />
                            )}
                        />
                    )),
                ...(isSkeleton ? [() => (
                    <FillAvailable
                        at="base"
                        explain="Skeleton name placeholder takes remaining row width beside rank and metric."
                        body={() => <Typography size="sm" isSkeleton />}
                    />
                )] : []),
                // the ranking metric ΓÇö distinct problems solved (NOT points)
                () => (
                    <Typography
                        size="sm"
                        weight="semibold"
                        color="accent-soft"
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? ["w-1/4"] : undefined}
                        text={solvedLabel}
                    />
                ),
            ]}
        />
    </Box>
)

/**
 * The GLOBAL coding leaderboard ΓÇö every user ranked by **distinct problems solved**
 * (`solvedCount`, the exact axis the backend `codingLeaderboard` orders on; NOT
 * points ΓÇö those are a different currency). A single capped reading column:
 * rank ┬╖ avatar ┬╖ name ┬╖ "N solved", with the signed-in viewer's row accent-tinted.
 * The viewer's own standing (rank / percentile / points) lives in the ProgressCockpit
 * above this on the page, so the board itself is just the list. **No podium** ΓÇö
 * coding is a pure ranked list. Self-contained: it reads the viewer id from the store
 * and drives its own SWR.
 */
export const CodingLeaderboard = () => {
    const t = useTranslations()
    // viewer identity highlights their own row
    const viewerId = useAppSelector((state) => state.user.user?.id) ?? null

    const { data, isLoading, error, mutate } = useSWR(
        ["coding-leaderboard", LEADERBOARD_LIMIT],
        async () => {
            const response = await queryCodingLeaderboard({
                request: { limit: LEADERBOARD_LIMIT },
            })
            return response.data?.codingLeaderboard.data ?? []
        },
    )

    const entries = data ?? []
    const isSkeleton = isLoading && !data

    // error beats a stale loading flag; empty only once settled (BLOCK-8 order).
    if (error) {
        return (
            <AsyncContentError
                title={t("PracticeHubPage.leaderboard.error")}
                onRetry={() => { void mutate() }}
                retryLabel={t("PracticeHubPage.retry")}
            />
        )
    }
    if (!isSkeleton && entries.length === 0) {
        return <AsyncContentEmpty title={t("PracticeHubPage.leaderboard.empty")} />
    }

    const listItems: Array<SurfaceCardListItem> = isSkeleton
        ? Array.from({ length: SKELETON_ROWS }, (_row, index) => ({
            key: `skeleton-${index}`,
            content: () => <LeaderboardRow rank={index + 1} isSkeleton />,
        }))
        : entries.map((entry, index) => ({
            key: entry.userId,
            content: () => (
                <LeaderboardRow
                    rank={index + 1}
                    entry={entry}
                    isViewer={!!viewerId && entry.userId === viewerId}
                    solvedLabel={t("PracticeHubPage.leaderboard.solved", { count: entry.solvedCount })}
                    youLabel={t("PracticeHubPage.leaderboard.you")}
                />
            ),
        }))

    return (
        // the board keeps a capped reading measure ΓÇö a width no closed union carries
        <Box className="mx-auto w-full max-w-2xl" principle="center-measure"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
        >
            <SurfaceCardList
                identity={{ tier: "block", component: "CodingLeaderboard" }}
                items={listItems}
            />
        </Box>
    )
}

"use client"

import React from "react"
import { Button, Label, ListBox, SearchField, Select, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import {
    RowsIcon,
    SquaresFourIcon,
} from "@phosphor-icons/react"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { StackH, StackV } from "@/components/frames/Stack"
import { usePracticeFilters } from "@/hooks/usePracticeFilters"
import {
    CODING_DIFFICULTY_META,
    DIFFICULTY_FILTERS,
    SORT_KEYS,
    STATUS_FILTERS,
} from "@/modules/utils/practice-hub"
import type {
    DifficultyFilter,
    SortKey,
    StatusFilter,
} from "@/modules/types/practice-hub"

/** Props for {@link PracticeFilters}. */
export type PracticeFiltersProps = Record<string, never>
/**
 * The PracticeHubPage catalog filter bar ΓÇö a title search box plus difficulty / status
 * filter chips (HeroUI Buttons, secondary when active / ghost when not), a sort
 * `Select`, and a group-by-domain toggle. The topic (domain) filter lives in the
 * {@link import("../PracticeRail").PracticeRail} sidebar, not here. Reads + writes
 * the URL-backed filter state itself ({@link usePracticeFilters}); composes blocks
 * + HeroUI only.
 *
 * @param props - optional className for the root element.
 */
export const PracticeFilters = () => {
    const t = useTranslations()
    const { filters, setFilters } = usePracticeFilters()

    return (
        <div className={"flex flex-col gap-4"}>
            {/* title search ΓÇö client-side filter over loaded problems */}
            <SearchField
                aria-label={t("PracticeHubPage.filters.searchPlaceholder")}
                value={filters.q}
                onChange={(value) => setFilters({ q: value })}
            >
                <Label className="sr-only">{t("PracticeHubPage.filters.searchPlaceholder")}</Label>
                <SearchField.Group>
                    <SearchField.SearchIcon />
                    <SearchField.Input placeholder={t("PracticeHubPage.filters.searchPlaceholder")} />
                    <SearchField.ClearButton />
                </SearchField.Group>
            </SearchField>

            {/* difficulty + status chip groups */}
            <StackV gap={4} principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                items={[
                    () => (
                        <FlexWrapButtonRadio
                            ariaLabel={t("PracticeHubPage.filters.difficultyAria")}
                            value={filters.difficulty}
                            onChange={(value) => setFilters({ difficulty: value as DifficultyFilter })}
                            items={DIFFICULTY_FILTERS.map((value) => ({
                                value,
                                content: value === "all"
                                    ? t("PracticeHubPage.filters.allDifficulties")
                                    : t(CODING_DIFFICULTY_META[value].labelKey),
                            }))}
                        />
                    ),
                    () => (
                        <FlexWrapButtonRadio
                            ariaLabel={t("PracticeHubPage.filters.statusAria")}
                            value={filters.status}
                            onChange={(value) => setFilters({ status: value as StatusFilter })}
                            items={STATUS_FILTERS.map((value) => ({
                                value,
                                content: t(`PracticeHubPage.filters.status.${value}`),
                            }))}
                        />
                    ),
                ]} />

            {/* sort dropdown + group toggle */}
            <StackH gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <StackV gap={3} principle="sibling-stack"
                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => <Label className="sr-only">{t("PracticeHubPage.filters.sortAria")}</Label>,
                                () => (
                                    <Select.Root<{ id: string }, "single">
                                        aria-label={t("PracticeHubPage.filters.sortAria")}
                                        selectedKey={filters.sort}
                                        onSelectionChange={(key) => setFilters({ sort: String(key) as SortKey })}
                                    >
                                        <Select.Trigger aria-label={t("PracticeHubPage.filters.sortAria")} className="w-fit min-w-40">
                                            <Select.Value>
                                                {() => (
                                                    <Typography type="body-sm">
                                                        {t(`PracticeHubPage.filters.sort.${filters.sort}`)}
                                                    </Typography>
                                                )}
                                            </Select.Value>
                                            <Select.Indicator />
                                        </Select.Trigger>
                                        <Select.Popover>
                                            <ListBox.Root aria-label={t("PracticeHubPage.filters.sortAria")}>
                                                {SORT_KEYS.map((value) => (
                                                    <ListBox.Item
                                                        key={value}
                                                        id={value}
                                                        textValue={t(`PracticeHubPage.filters.sort.${value}`)}
                                                    >
                                                        {t(`PracticeHubPage.filters.sort.${value}`)}
                                                    </ListBox.Item>
                                                ))}
                                            </ListBox.Root>
                                        </Select.Popover>
                                    </Select.Root>
                                ),
                            ]} />
                    ),
                    () => (
                        <Button
                            size="sm"
                            variant={filters.group ? "secondary" : "ghost"}
                            aria-pressed={filters.group}
                            onPress={() => setFilters({ group: !filters.group })}
                        >
                            {filters.group ? (
                                <SquaresFourIcon aria-hidden focusable="false" className="size-5" />
                            ) : (
                                <RowsIcon aria-hidden focusable="false" className="size-5" />
                            )}
                            {filters.group
                                ? t("PracticeHubPage.filters.grouped")
                                : t("PracticeHubPage.filters.flat")}
                        </Button>
                    ),
                ]} />
        </div>
    )
}

